(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-spec-decode-video-ar"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-1\">一 · 一次首帧超时的线上事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-2\">二 · 冗余从哪里来：帧间相关性与草稿可行性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-3\">三 · 接受准则的无偏性与它的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-4\">四 · 双份权重与双份 KV：显存是硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-5\">五 · 动态 k 与验证 batch 的高效区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-6\">六 · 适用与不适用：三条判断线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-7\">七 · 失效边界：当“草稿串行 + 验证并行”反噬时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-8\">八 · 失效边界：当“草稿”变成负债</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-9\">九 · 草稿阶段：KV cache 上的串行草拟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-10\">十 · 拼批：把 k 个候选折成一次前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-11\">十一 · 接受判定：逐位置比较与最长前缀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-12\">十二 · 提交与回退：KV 写入、重采样与丢弃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-13\">十三 · 动态调整：让验证批停在高效区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-14\">十四 · 验证批的边界：接受率塌缩、KV 双份与高效区间漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-15\">十五 · 加速比公式的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-16\">十六 · 接受准则的无偏性与最长前缀判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-17\">十七 · 伪代码：从草稿到验证的可实现流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-18\">十八 · 验证 batch 与 Blackwell 利用率的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-19\">十九 · 双份 KV 的显存账与长视频约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-20\">二十 · 动态 k 的控制律与失败模式对应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-21\">二十一 · 接受率的衰减曲线与验证批的收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-22\">二十二 · 请求形态：什么样的视频请求才吃得到这份收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-23\">二十三 · 长度分布：k 的上界由分布尾部决定，不由均值决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-24\">二十四 · 并发与批大小：验证 batch 与在线 batch 是两套账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-25\">二十五 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-26\">二十六 · 配方参数：把 k 写成接受率与 batch 形状的函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-27\">二十七 · 负载配方的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-28\">二十八 · 硬件档位：按目标模型显存加草稿余量切三档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-29\">二十九 · 并行拓扑：草稿与目标不必同构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-30\">三十 · 量化方案：目标保分布，草稿保速度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-31\">三十一 · KV策略：双份KV的分池、复制与淘汰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-32\">三十二 · 调度参数：动态k、草稿步数与SLO绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-33\">三十三 · 可复现的配置思路：从显存账到参数表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-34\">三十四 · 验证批的算术：k 放大的是激活还是权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-35\">三十五 · 双份 KV：长视频下最先崩的那堵墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-36\">三十六 · 通信：验证批与分离式部署的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-37\">三十七 · 功耗与热：验证批把能效曲线掰弯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-38\">三十八 · 规模上去以后，崩溃的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-39\">三十九 · 规模放大后的五道坎：显存、带宽、通信、功耗与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-40\">四十 · 精度漂移：接受率骤降的数值根因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-41\">四十一 · OOM：双份 KV 在长视频下的挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-42\">四十二 · 批抖动与路由不均：验证 batch 偏离高效区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-43\">四十三 · 尾延迟尖刺：拒绝回退的串行放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-44\">四十四 · 监控与回滚：把失败模式变成可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-45\">四十五 · 失效边界：接受率塌陷、显存挤压与批形漂移的联锁诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-46\">四十六 · 对照维度：先分清“改分布”与“保分布”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-47\">四十七 · 决策表：五类相邻算法的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-48\">四十八 · 收益公式下的选型算术</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-49\">四十九 · 显存与带宽：双份KV是选型的分水岭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-50\">五十 · 组合与排除：工程判断落在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-51\">五十一 · 边界在哪里：同族算法怎么选、何时不该用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-spec-decode-video-ar-sec-52\">五十二 · 选型边界：何时该用投机解码，何时该换别的路</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:563px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 563.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">草稿模型基于当前KV cache自回归提出k个候选帧latent（低分辨率…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型把k个候选拼成batch，一次前向并行计算各位置logits与KV。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按接受准则逐位置比较草稿与目标分布，取最长接受前缀。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接受前缀写入KV cache并输出；首个拒绝位置由目标模型重采样，丢弃其后…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">根据接受率动态调整k与草稿步数，维持验证batch在Tensor Core…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-spec-decode-video-ar-sec-1\">一 · 一次首帧超时的线上事故</h3>\n<p>某视频生成服务在 B200 单机上把目标 DiT 跑到接近饱和，单帧串行解码的 P95 却始终贴着 SLO 红线。运维为了压尾延迟，把每步采样链里的噪声重采样次数调低、把 VAE 解码切得更碎，尾延迟没降，反而把画质投诉率抬了上去。真正的病灶不在采样链，而在解码结构本身：自回归视频生成逐帧、逐 token 串行推进，每一步只产出极少量 latent token，却要把目标模型全部权重从 HBM 读一遍。单步时间由内存带宽而非算力决定，Tensor Core 大部分时间在等权重搬运，SM 利用率被采样链的串行依赖钉死。这就是本算法要解决的第一个具体问题：把「串行解码的单步带宽瓶颈」换成「草稿串行 + 验证并行」的批处理 GEMM 结构。它不解决画质与采样步数之间的矛盾——那是少步蒸馏与采样链设计的题目；也不解决长视频显存容量本身——那是 KV 量化与分块重叠解码的题目。它只处理一件事：在保持目标模型输出分布不变的前提下，把串行链路上可被并行验证的冗余挤出来。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-2\">二 · 冗余从哪里来：帧间相关性与草稿可行性</h3>\n<p>视频帧间强相关，相邻帧的 latent 在时空注意力下高度相似，这意味着目标模型在位置 $i$ 的决策，很大一部分可由一个更便宜的过程先猜出来。草稿模型因此可以是低分辨率、少步数、低精度的轻量版本：它基于当前 KV cache 自回归提出 $k$ 个候选帧 latent，代价远低于目标模型一次完整前向。目标模型随后把这 $k$ 个候选拼成一个 batch，一次前向并行算出各位置的 logits 与 KV，再逐位置比较草稿分布与目标分布，取最长一致前缀。这里的关键不是「猜得准」，而是「猜错也不污染输出」：接受准则保证被接受的 token 严格服从目标分布，被拒绝的位置由目标模型重采样，其后候选全部丢弃。于是算法把串行解码的 $k$ 步压缩为「草稿 $k$ 步串行 + 目标 1 次并行验证」，端到端时延的期望收益可写成</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</div>\n<p>其中 $a_j$ 是第 $j$ 个位置的接受率，$c_{\\text{draft}}/c_{\\text{target}}$ 是草稿与目标单步代价之比。公式直接暴露适用边界：分子随 $k$ 增长但被连乘的接受率迅速压平，分母随 $k$ 线性增长。当 $a_j$ 随 $j$ 快速衰减时，分子趋近于常数而分母继续涨，加速比跌破 1——这正是失败模式的第一条：草稿误差随 $k$ 累积，接受率骤降，验证开销反超收益，时延不降反升。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-3\">三 · 接受准则的无偏性与它的代价</h3>\n<p>接受判定按位置逐个进行，取满足下式的最长前缀 $m$：</p>\n<div class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</div>\n<p>这个比值检验不是启发式阈值，而是拒绝采样的一种变形，它保证最终输出序列的边缘分布与目标模型逐位置一致，即无偏。工程上这意味着投机解码不会像少步蒸馏那样改变采样链本身，画质与多样性不因加速而漂移；代价是把「猜」的自由度限制在分布一致性之内，草稿模型越偏离目标，可接受的前缀越短。对视频而言还有一层额外代价：验证阶段把 $k$ 个候选拼成 batch 走批处理 GEMM，batch 大小是 $k\\cdot N_{\\text{tok}}$，其中 $N_{\\text{tok}}$ 是每帧 latent token 数。这个 batch 必须落在 Blackwell Tensor Core 的高效区间，太小则 GEMM 形状瘦长、算力利用率低，太大则超出高效区间、寄存器与 TMEM 压力上升。于是 $k$ 不是越大越好，而是被「接受率」与「高效区间」两头夹住的调参量。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-4\">四 · 双份权重与双份 KV：显存是硬边界</h3>\n<p>算法要求草稿与目标两套权重同时驻留，且草稿模型要基于当前 KV cache 自回归，因此长视频下 KV 需要为草稿侧复制或共享一份视图。以 GB200 NVL72 的单机推理档位规划时，目标模型权重加草稿模型余量是硬约束；视频序列越长，KV 复制成本越显著，双份 KV 在长视频下挤爆显存是第二条失败模式。这与文本投机解码的显存账不同：文本 KV 随上下文线性增长但单 token 开销小，视频 latent token 维度高、帧数多，KV 体积本身已是容量规划的主项，再复制一份直接改变可服务的最长视频长度。因此适用边界的规模上限由「双份权重 + 双份 KV」共同决定，而不是由算力决定。工程判断是：先按目标模型显存加草稿余量定硬件档位，再用接受率反推可承受的 $k$ 与草稿步数，而不是先定 $k$ 再找卡。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-5\">五 · 动态 k 与验证 batch 的高效区间</h3>\n<p>接受率不是常数，它随场景漂移：镜头切换、快速运动、文本条件突变都会让帧间相关性下降，草稿误差累积加快。固定 $k$ 的部署在平稳镜头下收益可观，一遇切换就退化为纯开销。稳定性技巧因此是「无偏接受准则 + 动态 $k$」：运行时统计近期接受率，按接受率收缩或扩张 $k$ 与草稿步数，使验证 batch 始终落在 Tensor Core 高效区间。伪代码思路是：每轮验证后更新滑动窗口接受率 $\\hat{a}$，若 $\\hat{a}$ 低于阈值则令 $k\\leftarrow\\max(k_{\\min},\\lfloor k\\cdot\\hat{a}\\rfloor)$，若持续高于阈值则小幅增 $k$；同时草稿步数与 $k$ 联动，避免草稿侧串行步数本身成为新瓶颈。第三条失败模式正来自这里：$k$ 与草稿步数未随接受率调整时，验证 batch 偏离高效区间，并行验证的收益被抵消，表现为「加了投机解码但 P95 没动」。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-6\">六 · 适用与不适用：三条判断线</h3>\n<p>第一条线是帧间相关性。镜头平稳、运动缓慢、条件稳定的在线请求适合本算法，草稿误差可控，接受率高，验证 batch 能稳定吃满 Tensor Core；快速剪辑或多镜头切换的负载应先做场景切分再决定是否启用。第二条线是显存余量。长视频、高分辨率、大 latent 维度的请求让双份 KV 成本压过收益，此时应优先走 KV 量化或分块重叠解码，而不是加草稿模型。第三条线是 SLO 形态。以单帧时延为主的在线服务能从「串行转并行」直接受益；以吞吐为主的离线批处理本来就能靠大 batch 摊薄带宽瓶颈，投机解码的边际收益被稀释，反而增加显存占用与调度复杂度。三条线之外还有一条隐含约束：草稿模型必须与目标模型共享同一 token 化与 latent 空间，否则接受准则的比值检验失去意义。把这些边界画清楚，才能判断一次首帧超时的事故该修采样链、该修显存，还是该修解码结构——本算法只负责最后一种。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-7\">七 · 失效边界：当“草稿串行 + 验证并行”反噬时</h3>\n<p>线上事故的形态往往不是崩溃，而是时延曲线在长视频请求上悄悄塌陷。某次在线自回归视频服务在接入投机解码后，短片段（几十帧）的单帧时延确实下降，但当请求长度跨过某个门槛，P99 单帧时延反而高于未启用投机的基线，同时 GPU 显存告警频发。复盘指向三个耦合的失效点：草稿模型误差随候选长度 k 快速累积导致接受率骤降、双份 KV 在长视频下挤爆显存、以及 k 未随接受率收缩使验证 batch 偏离 Tensor Core 高效区间。这三者不是独立故障，而是同一条因果链上的三个环节——投机解码把串行解码转成“草稿串行 + 验证并行”，收益完全建立在“验证 batch 足够大且接受率足够高”这一前提上，前提一旦破裂，验证开销就反超收益。</p>\n<p>收益的定量边界可以直接从期望加速比读出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</div>\n<p>分子是接受前缀带来的有效推进量，分母是草稿 k 步加一次验证的相对代价。关键在于 $a_j$ 不是常数：视频帧间相关性强，但草稿模型（低分辨率、少步、低精度）的误差会随 k 增大逐位置累积，$\\prod_{j\\le i}a_j$ 随 i 迅速衰减，分子趋近于饱和；而分母随 k 线性增长。当 $c_{\\text{draft}}/c_{\\text{target}}$ 不够小、接受率又下滑时，加速比跌破 1——这就是事故中长视频段时延不降反升的数学解释。注意该式还隐含一个系统约束：验证 batch 为 $k\\cdot N_{\\text{tok}}$，k 过大时 batch 超出 Tensor Core 高效区间，$c_{\\text{target}}$ 本身会劣化，分母被二次放大。</p>\n<p>显存是第二条硬边界。草稿与目标模型双份权重常驻，KV 也要双份：草稿模型需要基于当前 KV cache 自回归提出候选，目标模型验证时又要为 k 个候选并行计算各位置 KV。短视频下这部分复制成本可忽略，长视频下 KV 随帧数线性增长，双份 KV 直接把显存预算吃掉，触发 OOM 或迫使批尺寸收缩——而批尺寸收缩又反过来削弱验证 batch 的 GEMM 效率。因此适用边界应写成显存约束下的联合判据：目标模型权重加草稿模型余量、再加双份 KV 的长视频峰值，必须落在单卡或单节点可容纳范围内；一旦越界，收益消失且稳定性受损。硬件档位规划要按“目标模型显存 + 草稿模型余量”留足，而不是按单模型估算。</p>\n<p>需要明确它不解决什么。它不改变采样链本身——相比少步蒸馏直接压缩去噪步数，投机解码保持目标模型分布不变，接受准则</p>\n<div class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</div>\n<p>取满足式的最长前缀 m，保证输出无偏，因此它无法突破目标模型自身的单步计算下限，也不能挽救一个本身帧间相关性弱、草稿误差不可控的场景。与普通文本投机解码相比，它额外背负帧 latent 的验证组织与长视频 KV 复制成本，这两项在文本侧几乎不存在。工程判断落在自适应策略上：以接受率为反馈信号动态收缩 k 与草稿步数，把验证 batch 钉在 Tensor Core 高效区间；接受率跌破阈值即退回纯自回归路径，宁可放弃投机收益也不让时延反噬。稳定性技巧是无偏接受准则加动态 k，而失败模式恰恰是这两者缺一——静态 k 在长视频上必然撞上误差累积与显存双墙。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>接受率随 k 衰减</td><td>分子饱和、分母线性增长</td><td>单帧时延反超基线</td></tr><tr><td>长视频双份 KV</td><td>显存峰值翻倍</td><td>OOM 或批尺寸收缩</td></tr><tr><td>k 未自适应</td><td>验证 batch 偏离高效区间</td><td>GEMM 效率下降、并行收益抵消</td></tr></tbody></table>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-8\">八 · 失效边界：当“草稿”变成负债</h3>\n<p>线上事故的典型形态不是草稿模型算得慢，而是它算得“太自信”。某长镜头生成任务里，草稿模型以低分辨率、少步数连续提出 k 个候选帧 latent，目标模型并行验证时，前两帧接受顺利，第三帧起草稿误差沿帧链放大——视频帧间相关性强，恰恰意味着草稿的偏差会被后续帧继承并放大，而不是被稀释。接受率 $a_j$ 随位置 j 快速衰减，验证 batch 里大量 token 被丢弃，目标模型白算一遍前向，端到端单帧时延不降反升。此时系统真正的代价不是算力，而是“验证了却被拒绝”的无效 GEMM 与随之而来的 KV 写入回滚。</p>\n<p>收益是否成立，取决于一个很窄的比值。设草稿单 token 成本 $c_{\\text{draft}}$、目标单 token 成本 $c_{\\text{target}}$，验证批为 $k\\cdot N_{\\text{tok}}$，则</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>分子是期望接受长度，分母是相对串行解码的归一化成本。当 $a_j$ 从 0.9 掉到 0.5 量级，分子趋近于 1 而分母仍随 k 线性增长，加速比跌破 1——这就是“验证开销反超收益”的解析形态。它说明该算法不解决草稿模型本身精度不足的问题，也不解决目标模型单步带宽瓶颈，只是把串行链换成“草稿串行 + 验证并行”；草稿质量差时，并行的部分全是沉没成本。</p>\n<p>第二类边界是显存。草稿与目标双份权重常驻，长视频下还要为草稿维护一份与目标对齐的 KV，KV 复制成本随上下文长度线性上升，在 NVL72 单机架高并发下极易触发显存不足，此时调度器被迫缩小 batch，反而牺牲了目标模型本身的吞吐。第三类边界是 k 与草稿步数未随接受率动态收缩：验证 batch 一旦偏离 Tensor Core 高效区间（过小则 GEMM 利用率低，过大则超出高效档位），并行验证的收益被抵消。因此适用判断应写成三条硬约束：帧间相关性强且草稿误差可控、双份权重与 KV 在显存预算内、k 能按接受率自适应收缩；任一不满足，收益消失，应退回纯目标模型串行解码或改用改变采样链本身的少步蒸馏路线。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-9\">九 · 草稿阶段：KV cache 上的串行草拟</h3>\n<p>整条流水线的入口是草稿模型。它读取目标模型当前已经提交的 KV cache，按帧顺序自回归地提出 <em>k</em> 个候选帧 latent。输入有三样：已接受的上下文 KV、当前帧的隐状态起点、以及草稿侧的超参（分辨率档位、采样步数、精度）。输出是 <em>k</em> 组候选 latent 及其对应的草稿分布 <span class=\"formula\">$$p_{\\text{draft}}(y_i\\mid y_{&lt;i})$$</span>，每个位置都要保留，因为接受准则逐位置需要它。</p>\n<p>草稿模型之所以便宜，是因为它在三个维度上同时降档：低分辨率（latent 网格更小，注意力矩阵规模按面积缩）、少步（采样链被截断到几步）、低精度（权重与激活走更窄的数值格式）。代价结构因此非常明确——草稿阶段仍然是串行的，<em>k</em> 步不能并行，其单步延迟由权重读取带宽与采样链长度共同决定。设草稿单步耗时 <span class=\"formula\">$$c_{\\text{draft}}$$</span>，则草稿阶段总代价约为 <span class=\"formula\">$$k\\cdot c_{\\text{draft}}$$</span>，并且这段延迟是纯串行、无法被 Tensor Core 并行度掩盖的。这是整条链路里唯一没有被并行化的部分，也是收益公式分母中那一项的来源。</p>\n<p>工程上要盯的是草稿侧的 KV 增长。草稿模型自己也要维护一份 KV，长度随已生成帧数线性增长；在长视频场景下，这份 KV 与目标模型的 KV 是两份独立存储。即便草稿侧做了降维（更少的头、更小的 head dim），其占用仍随视频时长单调上升，构成显存规划里必须预留的余量。一个具体例子：在 NVL72 单机架内做多路长视频在线请求时，草稿 KV 的复制成本会先于目标模型权重成为显存瓶颈，此时正确的动作是收缩并发路数而不是收缩 <em>k</em>。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-10\">十 · 拼批：把 k 个候选折成一次前向</h3>\n<p>草稿产出后，服务侧做的第一件事不是验证，而是重排。目标模型不接受“逐帧喂”的调用方式，而是把 <em>k</em> 个候选帧 latent 沿 batch 维拼成一个验证批，一次前向同时算出所有位置的 logits 与 KV。输入是 <em>k</em> 份候选 latent 加上共享的上下文 KV；输出是 <em>k</em> 组目标分布 <span class=\"formula\">$$p_{\\text{tgt}}(y_i\\mid y_{&lt;i})$$</span> 与这 <em>k</em> 个位置的 KV 条目。</p>\n<p>这一步的代价要按验证批的实际形状算，而不是按单帧算。验证 batch 的 token 规模是 <span class=\"formula\">$$\\text{verify batch}=k\\cdot N_{\\text{tok}}$$</span>，其中 <span class=\"formula\">$$N_{\\text{tok}}$$</span> 是单帧 latent token 数。这个乘积决定了 GEMM 的 M 维：<em>k</em> 太小，M 维填不满，SM 上 tcgen05 的 MMA 流水吃不满，并行验证的收益被抵消；<em>k</em> 太大，验证批超出 Tensor Core 高效区间，注意力部分的 KV 读取量随之膨胀，单次验证的时延抬升。存在一个由目标模型宽度与显存带宽共同决定的甜点区，服务实现应当把它作为配置常量而不是运行期猜测。</p>\n<p>拼批还带来一个容易被忽略的副作用：验证前向要为 <em>k</em> 个位置都算出 KV，但其中只有被接受的前缀会被真正写入。这意味着验证阶段存在 KV 写放大，写放大倍数上界是 <em>k</em>，实际倍数等于接受前缀长度占比的倒数。在 KV 带宽紧张的长视频负载下，这部分无效写入是实打实的显存带宽开销，而不是零成本。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-11\">十一 · 接受判定：逐位置比较与最长前缀</h3>\n<p>验证前向拿到两组分布后，接受准则按位置逐个比较。判据写成：</p>\n<div class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</div>\n<p>取满足该式的最长前缀 <em>m</em>。这个形式的关键在于它是无偏的：接受与否的随机化恰好补偿了草稿分布与目标分布的偏差，使得最终输出序列的分布与纯目标模型解码完全一致。换句话说，投机解码不改变采样链本身（这一点与少步蒸馏那条路线正相反，后者动的是采样链），它只是把串行解码改写成草稿串行加验证并行。</p>\n<p>判定的代价主要是访存而非算力。逐位置比较需要对 <em>k</em> 个位置的分布做读取与归一化比值计算，若词表或 latent 码本较大，这一步是纯带宽受限的小算子，容易在 GPU 上形成 kernel launch 碎片。实现上应把它融进验证前向的尾部或用一个轻量 kernel 一次处理整个验证批，避免 <em>k</em> 次独立启动。判定输出是一个标量 <em>m</em> 加一个拒绝位置索引，后续所有动作都由这两个数驱动。</p>\n<p>接受率 <span class=\"formula\">$$a_j=\\Pr[\\text{accept}_j]$$</span> 的衰减形态决定了整条链路的成败。视频帧间相关性强，前几帧的草稿通常准，但草稿模型误差会随 <em>k</em> 增大快速累积，<span class=\"formula\">$$a_j$$</span> 随 <em>j</em> 上升而下降。一个具体场景：镜头缓慢平移的连续帧，草稿在 <em>k</em>=4 内接受率保持高位；一旦切镜或出现快速运动，第 2 帧起接受率骤降，此时验证批里大部分位置都被丢弃，验证开销反超收益，端到端时延不降反升。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-12\">十二 · 提交与回退：KV 写入、重采样与丢弃</h3>\n<p>接受前缀写入目标模型 KV cache 并作为输出提交，这是整条链路里唯一产生持久状态的动作。写入量等于 <em>m</em> 个位置的 KV，代价是显存带宽加容量占用；在长视频下，每次提交都在推高 KV 长度，进而推高后续所有前向的注意力读取量。这就是为什么提交步必须与 KV 量化、分块策略协同——本卷其他条目讨论的 2bit KV 量化正是在这一步生效的。</p>\n<p>首个拒绝位置由目标模型重采样，其后所有候选一律丢弃。重采样是一次单位置前向，代价接近一次普通解码步，但它把链路重新拉回串行。丢弃动作看似免费，实则意味着草稿阶段为后段候选付出的 <span class=\"formula\">$$(k-m)\\cdot c_{\\text{draft}}$$</span> 全部沉没。因此回退频率直接决定了草稿算力的有效利用率，而回退频率又由接受率分布决定。</p>\n<p>这里有一个工程判断值得写进配置：当 <em>m</em>=0（首个位置即被拒）连续出现时，说明草稿模型与目标模型在该上下文上已经脱钩，继续按原 <em>k</em> 草拟只是在烧算力。服务应把这种情况作为触发信号，进入下一节的动态调整逻辑，而不是等统计窗口滑完。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-13\">十三 · 动态调整：让验证批停在高效区间</h3>\n<p>最后一步是反馈控制。根据近期接受率动态调整 <em>k</em> 与草稿步数，目标是让验证批规模 <span class=\"formula\">$$k\\cdot N_{\\text{tok}}$$</span> 稳定落在 Tensor Core 高效区间，同时不让草稿串行段过长。收益的期望形态由下式给出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>分子是每个验证周期平均产出的帧数，分母是相对单步解码的代价比。这个式子给出两条硬约束：其一，<em>k</em> 增大时分子受 <span class=\"formula\">$$a_j$$</span> 衰减压制，收益饱和甚至回落；其二，分母随 <em>k</em> 线性增长，只要 <span class=\"formula\">$$c_{\\text{draft}}/c_{\\text{target}}$$</span> 不够小，大 <em>k</em> 必然亏。因此调整策略不是“接受率高就加大 <em>k</em>”，而是同时约束两端：接受率高时加 <em>k</em> 以填满验证批，接受率下滑时先减草稿步数（降 <span class=\"formula\">$$c_{\\text{draft}}$$</span>）再减 <em>k</em>。</p>\n<p>代价体现在两个层面。算力层面，<em>k</em> 与草稿步数的每次变更都会改变验证批形状，形状跳变会引起 kernel 选择与 workspace 重新规划，频繁抖动本身有开销，所以调整应当是带滞回的离散档位而非连续调节。显存层面，双份权重加双份 KV 是这条路线绕不开的固定成本，硬件档位必须按“目标模型显存 + 草稿模型余量 + 长视频 KV 增长”三者之和来规划，而不是按目标模型单独规划。在 GB200/GB300 NVL72 这类高带宽域内，权重侧的余量相对好安排，真正吃紧的是随视频时长增长的 KV 复制成本——这也是该机制规模上限的物理来源。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-14\">十四 · 验证批的边界：接受率塌缩、KV 双份与高效区间漂移</h3>\n<p>把这条流水线按数据流再走一遍，边界就露在每一步的“代价归属”上。草稿步：输入是当前 KV cache 与上一帧 latent，输出 k 个候选帧 latent，代价是 k 次串行小模型前向——它并不省串行，只是把串行从目标模型挪到更便宜的模型上，所以草稿步的每步延迟必须显著低于目标步，否则整条链的串行段没有缩短。验证步：k 个候选被拼成 batch，一次前向算出各位置 logits 与 KV，代价是一次批处理 GEMM 加上为 k 份候选各写一份 KV，显存瞬时占用随 k 线性上升。接受步：逐位置比较两个分布，取满足 <span class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</span> 的最长前缀 m，代价近乎为零但决定后续全部收益；回退步：首个拒绝位置由目标模型重采样、丢弃其后候选，代价是一次单点前向外加被丢弃候选的 KV 作废——这部分算力是纯浪费，且随 k 增大而增大。</p>\n<p>失效条件的第一条是接受率随 k 的塌缩。视频帧间相关性强，但草稿模型（低分辨率、少步、低精度）的误差在自回归链上逐位置复合，<span class=\"formula\">$$a_j=\\Pr[\\text{accept}_j]$$</span> 随 j 单调下滑，期望加速比 <span class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$$</span> 的分子被连乘项迅速压平，分母却随 k 线性增长。当 <span class=\"formula\">$$\\prod_{j\\le i}a_j$$</span> 衰减快于 <span class=\"formula\">$$c_{\\text{draft}}/c_{\\text{target}}$$</span> 的补偿，加速比跌破 1，时延不降反升。工程判断是：k 不该是常数，而应由最近若干请求的实测接受长度反推——按接受率自适应收缩 k，把 k 压到“最长接受前缀的期望值再加一点余量”附近，让被丢弃候选的浪费比例可控。</p>\n<p>第二条是显存与带宽的双份成本。草稿与目标各持一份权重，长视频下还要各持一份随帧增长的 KV；验证步为 k 个候选写入的 KV 在拒绝后作废，等于用带宽买了废数据。视频 KV 的复制成本比文本更尖锐，因为序列长度按帧累积，KV 体积随时长增长而非按 token 数缓慢增长，双份 KV 在长视频上直接挤压可用显存，触发容量规划里的硬上限。部署时硬件档位必须按“目标模型权重 + 草稿模型权重 + 两份长视频 KV + 验证 batch 峰值激活”来配，任何一项按单模型估算都会在长视频上失守。</p>\n<p>第三条是高效区间漂移。验证 batch 为 <span class=\"formula\">$$k\\cdot N_{\\text{tok}}$$</span>，只有落在 Tensor Core 高效区间时，批处理 GEMM 的利用率才抵得过草稿步的额外开销；k 过大使 batch 超出高效区间、k 过小又喂不饱 Tensor Core，两端都让“并行验证”的名义收益落空。于是动态调整不只是为了接受率，也是为了把 <span class=\"formula\">$$k\\cdot N_{\\text{tok}}$$</span> 钉在高效区间内——接受率高时放大 k 吃满 GEMM，接受率下滑时收缩 k 并同步减少草稿步数，避免用更大的 batch 去验证更不可信的候选。适用边界由此清晰：帧间相关性强且草稿误差可控、显存能容纳双份权重与长视频 KV、k 能随接受率实时收敛，三者同时成立时收益才在；任一条件破掉，回退到纯目标模型串行解码反而是更稳的容量选择。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-15\">十五 · 加速比公式的逐项拆解</h3>\n<p>本片段的核心是把“草稿串行 + 验证并行”的收益写成可核算的表达式，而不是凭直觉判断投机解码是否划算。给定事实给出的形式是：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</div>\n<p>分子是“一次投机轮次实际推进的 token 数期望”。基线串行解码一轮推进 1 个 token，所以常数项 1 代表至少被接受的首个位置；求和项 $\\sum_{i=1}^{k}\\prod_{j\\le i}a_j$ 是第 $i$ 个位置被接受的联合概率，即前 $i$ 个位置全部通过接受准则的概率。注意这里是连乘而非单点概率：第 3 个位置被接受，要求第 1、2、3 个位置同时被接受，因此 $a_j$ 随 $j$ 增大而衰减的形态直接决定分子能否随 $k$ 线性增长。分母是“一次投机轮次的时间成本”相对单步目标模型前向的比值：$1$ 是目标模型验证一次前向的基准开销，$k\\,c_{\\text{draft}}/c_{\\text{target}}$ 是草稿模型串行提出 $k$ 个候选所付出的代价，$c_{\\text{draft}}$ 与 $c_{\\text{target}}$ 分别是草稿与目标单步的计算/带宽成本。这个式子的关键一步推导在于：把串行解码的 $1+k$ 步压缩成“$k$ 步草稿串行 + 1 次目标并行验证”，并用期望接受长度替换实际推进长度——收益不是 $k$ 倍，而是被接受率连乘与草稿成本同时折损后的净值。</p>\n<p>工程含义很直接：当 $a_j$ 接近 1（帧间强相关、草稿误差可控），分子近似 $1+k$，分母只要 $c_{\\text{draft}}/c_{\\text{target}}$ 足够小，加速比就接近 $k$；当 $a_j$ 快速衰减，分子饱和在 $1+\\sum\\prod a_j$ 的有限值上，而分母仍随 $k$ 线性增长，加速比必然在某个 $k^\\*$ 处达到峰值后回落。这就是“接受率低时验证开销反超收益”的数学形态，也是动态调整 $k$ 的理论依据：$k$ 不是越大越好，而是让 $\\partial\\,\\mathbb{E}[\\text{speedup}]/\\partial k=0$ 的驻点。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-16\">十六 · 接受准则的无偏性与最长前缀判定</h3>\n<p>接受准则给定为：</p>\n<div class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</div>\n<p>取满足该式的最长前缀 $m$，保证输出分布与目标模型一致（无偏）。逐项解释：比值 $p_{\\text{tgt}}/p_{\\text{draft}}$ 是重要性权重，衡量草稿分布对目标分布的“欠采样”程度；连乘到 $m$ 是把逐位置的重要性权重累积成前缀级似然比；与均匀随机数 $u$ 比较，等价于以概率 $\\min(1,\\prod_{i\\le m}\\text{ratio})$ 接受该前缀。推导的关键一步是：对每个位置独立地做“以概率 $\\min(1,p_{\\text{tgt}}/p_{\\text{draft}})$ 接受、否则从残差分布重采样”的拒绝采样，其边缘分布恰好还原 $p_{\\text{tgt}}$；把逐位置判定串起来并要求前缀整体通过，就得到上式。工程上不必真的逐位置掷骰子再拼接，而是先算累积对数似然比 $\\sum_{i\\le m}\\log p_{\\text{tgt}}-\\log p_{\\text{draft}}$，与 $-\\log u$ 比较，一次前缀扫描即可定位最长可接受 $m$。</p>\n<p>视频场景的特殊性在于 $y_i$ 是帧 latent token 序列而非文本 token，$p_{\\text{tgt}}$ 与 $p_{\\text{draft}}$ 都是 DiT 输出的 latent 分布（经采样链变换后的分布），因此比值必须在同一参数化下计算，否则无偏性失效。代价体现在：每个候选位置都要保存目标与草稿两套 logits（或至少其对数比），验证 batch 为 $k\\cdot N_{\\text{tok}}$ 时这部分中间激活的显存随 $k$ 线性增长；同时前缀扫描是串行依赖，虽然计算量小，但在长视频高帧率下会成为验证后的固定尾延迟。一个具体例子：若 $k=4$、每帧 $N_{\\text{tok}}$ 个 latent token，验证 batch 就是 $4N_{\\text{tok}}$，目标模型一次前向要同时产出这 $4N_{\\text{tok}}$ 个位置的 logits 与 KV，前缀判定只在这批结果上做一次扫描，拒绝位置之后的所有候选直接丢弃，其 KV 不写入 cache。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-17\">十七 · 伪代码：从草稿到验证的可实现流程</h3>\n<p>把机制步骤落到可实现层面，需要明确三件事：草稿循环的输入输出、验证 batch 的拼装方式、以及接受/回退的写回顺序。下面给出伪代码思路（非 <code>&lt;pre&gt;</code> 形式，按行描述）：</p>\n<ul>\n<li>输入：当前 KV cache $C$、已生成帧序列、草稿模型 $M_d$、目标模型 $M_t$、候选数 $k$、草稿步数 $s$。</li>\n<li>草稿阶段：以 $C$ 为条件，$M_d$ 自回归执行 $k$ 步（每步可含 $s$ 个少步采样），每步输出候选帧 latent $y_i$ 及其草稿分布 $p_{\\text{draft}}(y_i\\mid y_{&lt;i})$，同时把草稿自身的 KV 追加到临时缓冲 $C_d$；此阶段是串行的，延迟为 $k\\cdot c_{\\text{draft}}$。</li>\n<li>拼批：把 $k$ 个候选 latent 拼成 batch，形状为 $k\\cdot N_{\\text{tok}}$，连同 $C$ 一起送入 $M_t$ 做一次前向，得到各位置的 $p_{\\text{tgt}}$ 与目标 KV 增量 $\\Delta C_t$；这是唯一的并行 GEMM 阶段，落在 Tensor Core 高效区间。</li>\n<li>判定：对 $i=1\\ldots k$ 累积对数似然比，与 $-\\log u$ 比较，取最长满足前缀 $m$；若 $m=0$ 则全部拒绝。</li>\n<li>写回：把前 $m$ 个位置的 $\\Delta C_t$ 写入 $C$ 并输出对应帧；对第 $m+1$ 个位置，用 $M_t$ 从残差分布重采样一个 token 并写入 $C$，丢弃 $m+1$ 之后的所有候选及其 KV。</li>\n<li>自适应：用本轮观测的接受率 $\\hat a=m/k$ 更新 $k$ 与 $s$，使下一轮验证 batch 仍处于高效区间；接受率持续偏低时收缩 $k$，接受率接近 1 时适度增大 $k$ 但受显存上限约束。</li>\n</ul>\n<p>这段伪代码的代价点在于：草稿阶段的 $C_d$ 与目标阶段的 $\\Delta C_t$ 是两份 KV，长视频下 $C$ 本身已经很大，复制或镜像一份草稿 KV 会直接抬高显存占用；因此实现上更常见的做法是草稿模型复用目标的 KV 布局、只保留少量草稿层 KV，或在拒绝后丢弃草稿 KV 而不做持久化。另一个代价是验证 batch 的 $k\\cdot N_{\\text{tok}}$ 必须落在 Tensor Core 高效区间：$k$ 过小则 batch 太窄、GEMM 利用率低，$k$ 过大则超出高效区间且显存吃紧，这正是动态 $k$ 要维持的窗口。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-18\">十八 · 验证 batch 与 Blackwell 利用率的耦合</h3>\n<p>公式中的 $\\text{verify batch}=k\\cdot N_{\\text{tok}}$ 不是装饰项，它把投机解码的收益与硬件利用率绑在一起。串行解码时单步 batch 只有 1 个 token（或 1 帧），GEMM 的 M 维极窄，Tensor Core 大部分时间在等内存；验证阶段把 $k$ 个候选拼成一个 batch，M 维变成 $k\\cdot N_{\\text{tok}}$，GEMM 从“窄而频繁”变成“宽而少次”，这是端到端时延可降的硬件根源。代价是：验证前向的计算量约为单步的 $k$ 倍（忽略 KV 读取的摊薄），但 KV 读取从 $k$ 次变成 1 次，带宽开销被摊薄，所以净收益取决于 $k$ 是否落在高效区间。</p>\n<p>具体例子：设目标模型单步前向在 batch=1 时受内存带宽限制、Tensor Core 利用率低；当 $k\\cdot N_{\\text{tok}}$ 增大到能填满一个 MMA tile 高度时，单次前向的吞吐显著提升，而这次前向替代了 $k$ 次串行前向。反之，若接受率低导致有效推进长度 $m$ 远小于 $k$，这次宽 batch 前向的大部分计算被浪费在随后被丢弃的候选上，验证开销反超收益。工程判断是：把 $k$ 的上界设为“验证 batch 不超过高效区间上沿”与“显存余量允许的 KV 增量”两者的较小值，再用接受率反馈下调，而不是固定一个经验常数。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-19\">十九 · 双份 KV 的显存账与长视频约束</h3>\n<p>部署配方明确指出草稿与目标模型双份权重与 KV 占用显存，长视频下 KV 复制成本高。把这项代价写进容量规划：设目标模型 KV 每帧占用 $S_{\\text{tgt}}$、草稿模型 KV 每帧占用 $S_{\\text{draft}}$，视频长度 $L$ 帧，则 KV 总占用约为 $L(S_{\\text{tgt}}+S_{\\text{draft}})$，再加上双份权重 $W_{\\text{tgt}}+W_{\\text{draft}}$。加速比公式的分母里 $c_{\\text{draft}}/c_{\\text{target}}$ 只反映单步计算成本，没有反映这份显存代价；因此收益判断必须叠加显存约束：当 $L$ 增大到 $L(S_{\\text{tgt}}+S_{\\text{draft}})$ 逼近显存上限时，要么放弃草稿 KV 的持久化（每轮重建），要么收缩 $k$ 以减少验证 batch 的中间激活，要么退化为纯目标模型解码。</p>\n<p>一个具体机制是“拒绝即丢弃”：草稿阶段产生的 $C_d$ 只在验证期间存在，验证完成后仅保留被接受前缀对应的目标 KV，草稿 KV 全部释放。这样显存峰值出现在验证瞬间，等于 $C$ 加上验证 batch 的中间激活，而非 $C$ 加上整段草稿 KV。代价是草稿模型每轮都要从 $C$ 重新建立条件，无法跨轮复用草稿 KV，草稿阶段的串行成本无法摊薄——这与“长视频下 KV 复制成本高”是同一枚硬币的两面，实现时按 $L$ 与显存余量在“复用草稿 KV”和“每轮重建”之间切换。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-20\">二十 · 动态 k 的控制律与失败模式对应</h3>\n<p>稳定性技巧是接受准则无偏加动态 $k$。把动态 $k$ 写成控制律：每轮观测接受率 $\\hat a=m/k$，若 $\\hat a$ 高于上阈值则 $k\\leftarrow\\min(k+\\Delta k,k_{\\max})$，若低于下阈值则 $k\\leftarrow\\max(k-\\Delta k,k_{\\min})$，其中 $k_{\\max}$ 由验证 batch 的高效区间上沿与显存余量共同决定，$k_{\\min}$ 通常为 1（退化为纯目标解码）。草稿步数 $s$ 同步调整：$s$ 增大提高草稿质量但抬高 $c_{\\text{draft}}$，在接受率已高时增大 $s$ 的边际收益递减，反而拖慢分母。</p>\n<p>这条控制律直接对应三个失败模式：其一，草稿误差随 $k$ 快速累积使接受率骤降——表现为 $\\hat a$ 连续低于下阈值，控制律收缩 $k$，若收缩到 $k_{\\min}$ 仍无收益则说明该场景不适合投机解码；其二，双份 KV 在长视频下挤爆显存——表现为验证瞬间的显存峰值触顶，需切换到“拒绝即丢弃”或降低 $k_{\\max}$；其三，$k$ 过大使验证 batch 超出高效区间——表现为验证前向时间不随 $k$ 线性增长而是超线性，控制律应以实测的验证前向时间为反馈量，而非仅看接受率。工程判断落在最后这一点：接受率决定“值不值得验证”，验证前向时间决定“验证 batch 是否还在高效区间”，两个反馈量共同约束 $k$，缺一不可。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-21\">二十一 · 接受率的衰减曲线与验证批的收益边界</h3>\n<p>把速度公式拆开看，分子$1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j$是“平均每个验证批产出多少被接受的token”，分母$1+k\\,c_{\\text{draft}}/c_{\\text{target}}$是“一个验证批相对一次目标模型前向的时间倍数”。真正决定成败的是连乘项$\\prod_{j\\le i}a_j$：视频帧间相关性强，$a_1$往往不低，但草稿模型是低分辨率、少步、低精度的近似，其误差沿自回归链逐位置放大，$a_j$随$j$单调下滑。设$a_j=a_1\\rho^{j-1}$（$\\rho&lt;1$为衰减因子），则$\\prod_{j\\le i}a_j=a_1^{i}\\rho^{i(i-1)/2}$——指数里带$i^2$，这是k不能随便调大的根本原因。对$k$求导令分子增益与分母开销相等，可得最优$k^\\*$满足$a_{k^\\*}\\approx c_{\\text{draft}}/c_{\\text{target}}$，即“下一个位置的接受概率跌到草稿/目标单步代价比时就该停”。工程上不必解这个方程，直接测最近窗口的滑动接受率，当$a_{k}$低于该比值即收缩k。</p>\n<p>失效条件可以列成一张判定表，比定性描述更好用：</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>阈值判据</th><th>系统后果</th></tr></thead><tbody><tr><td>窗口接受率$\\bar a$</td><td>$\\bar a&lt;c_{\\text{draft}}/c_{\\text{target}}$</td><td>验证开销反超，单帧时延不降反升</td></tr><tr><td>验证批$k\\cdot N_{\\text{tok}}$</td><td>低于Tensor Core高效区间下沿</td><td>GEMM利用率塌陷，并行验证白做</td></tr><tr><td>双份KV占用</td><td>目标+草稿KV超过单卡/HBM上限</td><td>长视频中途OOM或被迫降batch</td></tr></tbody></table>\n<p>第一行的含义值得展开：接受率低时，验证批里大部分候选被丢弃，目标模型算了$k\\cdot N_{\\text{tok}}$个位置却只输出一两个token，等于用一次完整前向的显存带宽换极少的有效输出。视频场景尤其危险，因为帧latent维度远大于文本token，验证批的KV写入量按$k\\cdot N_{\\text{tok}}$线性增长，HBM带宽被验证本身吃掉。反过来，$k$太小则验证批落在Tensor Core高效区间下沿之外，批处理GEMM的并行度不足以摊薄权重读取，收益同样消失——这就是“k与草稿步数未随接受率动态调整”这一失败模式的机理。</p>\n<p>显存侧要单独算一笔账：草稿模型权重虽小，但其KV必须与目标模型KV同步维护，长视频下KV随帧数线性增长，双份复制意味着同样的帧历史被存两遍。可行的工程判断是把草稿KV做成目标KV的低秩/低精度投影而非独立全量副本，并在接受前缀写回时只保留目标侧权威KV；当预估KV总量逼近显存上限，优先缩k而不是缩分辨率，因为缩分辨率会进一步压低$a_j$、把系统推入第一行的失效区。适用边界由此清晰：帧间相关性强且草稿误差可控时收益成立，一旦接受率跌破代价比或KV复制成本压过并行验证的节省，这套方案就该退回纯目标模型解码。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-22\">二十二 · 请求形态：什么样的视频请求才吃得到这份收益</h3>\n<p>投机解码在自回归视频里不是普适加速器，它挑请求。判断一个请求是否落在配方内，先看三件事：帧间相关性强不强、单次请求的帧数够不够长、草稿模型在同一上下文上的误差是否可控。帧间相关性强意味着草稿模型基于当前 KV cache 提出的 k 个候选帧 latent 有较大概率被目标模型整段接受，接受率 $a_j$ 在 j 方向上衰减得慢；帧数够长意味着草稿串行那一段的固定开销能被摊薄；误差可控意味着草稿的低分辨率/少步近似没有偏离目标分布太远。三者同时成立，验证 batch 才有稳定的高接受前缀可拿。</p>\n<p>反过来，请求形态一旦偏离，配方立刻失效。镜头切换频繁、场景跳变的请求，帧间相关性被打断，草稿提出的候选帧在第一个位置就被拒，最长接受前缀退化为 1，验证 batch 里 k−1 个候选全是废计算。首帧或极短请求（只生成两三帧）没有足够的串行深度让草稿段与验证段拉开差距，草稿模型的前向开销直接压在关键路径上。这类请求应当走普通自回归路径，不进投机通道。</p>\n<p>工程上给请求打标签的成本很低：按提示词类型、镜头稳定性启发式、历史接受率分桶即可。分桶后按桶配置 k 与草稿步数，比全局一个 k 稳得多。一个具体例子：连续长镜头、慢运镜的生成请求，历史接受率长期处于高位，可以给较大的 k；而快速剪辑类请求，历史接受率低，直接降到 k=2 甚至关闭投机，避免验证开销反超。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-23\">二十三 · 长度分布：k 的上界由分布尾部决定，不由均值决定</h3>\n<p>长度分布对配方的影响不在均值，在尾部。自回归视频的请求长度分布通常是重尾的：大量中等长度请求加少量超长请求。k 的选择若按均值调优，长尾请求上会出问题——k 越大，草稿误差随 k 累积越明显，长视频后段的接受率往往比前段低，因为 KV cache 越长、上下文越复杂，草稿模型的近似误差被放大。用公式看，端到端加速比的期望是</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</div>\n<p>分子随 k 增长的速度由连乘 $\\prod_{j\\le i}a_j$ 决定，分母随 k 线性增长。当 $a_j$ 在长视频后段明显下滑时，连乘项迅速塌缩，分子趋近于饱和，分母继续涨，加速比出现拐点后下降。所以 k 的上界应当由长度分布尾部的接受率曲线决定：取尾部请求上使分子增量仍大于分母增量的最大 k。</p>\n<p>长度分布还决定验证 batch 的形状。验证 batch 是 $k\\cdot N_{\\text{tok}}$ 个 token 拼成的批处理 GEMM，$N_{\\text{tok}}$ 是每帧的 latent token 数。短请求下 $N_{\\text{tok}}$ 小，k 稍大就能把 batch 填到 Tensor Core 高效区间；长请求下 $N_{\\text{tok}}$ 本身已大，k 再大就让 batch 超出高效区间，GEMM 的 tile 利用率反而下降。这就是为什么长度分桶必须和 k 联动：短请求给大 k 填 batch，长请求给小 k 防溢出。</p>\n<p>代价落在显存与带宽上。长视频请求的 KV cache 本来就大，草稿模型还要复制一份对应长度的 KV，双份 KV 在长尾请求上最容易挤爆显存。一个具体例子：同一套部署里，中等长度请求跑得顺，一旦排进超长请求，KV 复制成本叠加验证 batch 的激活占用，显存水位顶到上限，调度器被迫降低并发，吞吐塌陷。配方必须给长尾请求单独留显存余量，或对超长请求关闭投机。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-24\">二十四 · 并发与批大小：验证 batch 与在线 batch 是两套账</h3>\n<p>并发维度上最容易犯的错，是把验证 batch 当成在线 batch 的一部分去算吞吐。验证 batch 是单请求内部的并行度，$k\\cdot N_{\\text{tok}}$ 个 token 一次前向；在线 batch 是跨请求的并发数。两者共享同一块 SM 与 Tensor Core 资源，但优化目标不同：验证 batch 要落在高效区间吃满 GEMM，在线 batch 要摊薄权重读取的带宽成本。并发升高时，每个请求的验证 batch 都在抢同一批 Tensor Core，单请求的验证延迟被拉长，SLO 以单帧时延为主时，这个拉长直接体现为违约。</p>\n<p>配方上的做法是给并发设一个与 k 联动的上限。总验证 token 量近似为 $\\text{并发}\\times k\\cdot N_{\\text{tok}}$，这个量超过 Tensor Core 在单帧时延预算内能消化的吞吐时，就必须降 k 或降并发。降 k 会降低单请求加速比但保住时延，降并发会保住单请求时延但牺牲吞吐。哪个优先取决于 SLO 形态：单帧时延硬约束的场景降 k，吞吐优先的场景降并发并接受时延上浮。</p>\n<p>另一个代价是草稿模型的前向也占资源。草稿段是串行的，每个请求的草稿前向无法与其他请求的验证段完全重叠时，SM 出现空转。并发太低时草稿段占比高，Blackwell 的利用率上不去；并发太高时验证段互相挤压。存在一个使总利用率最高的并发窗口，窗口位置随 k、$N_{\\text{tok}}$、草稿步数移动。工程上通过实测扫描这个窗口，把调度器的并发上限钉在窗口内，而不是拍一个固定值。</p>\n<p>具体例子：一个部署把并发从低位往上调，起初吞吐线性涨，到某一档后单帧时延开始超 SLO，继续加并发吞吐不再涨而时延继续恶化——这就是验证 batch 总量越过 Tensor Core 消化能力的信号，此时应停止加并发，转而按接受率收缩 k。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-25\">二十五 · 负载不对时的三种塌陷</h3>\n<p>第一种是接受率塌陷。帧间相关性强但草稿误差随 k 快速累积，$a_j$ 沿 j 方向陡降，连乘项在几步内趋零。此时验证 batch 里大部分候选被拒，目标模型的重采样次数上升，串行回退路径变长，端到端时延不降反升。识别信号是滑动窗口内的平均接受前缀长度持续低于阈值，且 k 越大越差。处置是自适应收缩 k 与草稿步数，把验证 batch 拉回高效区间，必要时对该请求类型关闭投机。</p>\n<p>第二种是显存塌陷。草稿与目标双份权重加双份 KV，长视频下 KV 复制成本高。KV cache 随帧数线性增长，草稿模型那份复制在长请求上不产生额外信息却实打实占显存。显存水位逼近上限时，调度器降低并发，吞吐掉；更糟的是触发重分配或换出，单帧时延出现尖峰。处置是按请求长度分档预留显存，超长档直接不走投机，或在草稿侧用更省的 KV 表示——但这属于别的条目的主题，这里只指路。</p>\n<p>第三种是 batch 形状塌陷。k 与草稿步数未随接受率动态调整，验证 batch 偏离 Tensor Core 高效区间。k 过大时 batch 超出高效区间，GEMM tile 利用率下降，并行验证的收益被抵消；k 过小时 batch 填不满，Tensor Core 空转，草稿段的串行开销占比过高。两种偏离都表现为“投机动了但没快”，实测加速比接近 1 甚至小于 1。识别信号是验证段的 SM 利用率与 GEMM 吞吐同时低于预期，处置是把 k 作为接受率的函数动态求解，而不是静态配置。</p>\n<p>三种塌陷的共同点是：配方假设的负载形态与实际流量不匹配。部署侧应当在入口做请求分类，把不适合的请求挡在投机通道外，而不是让它们在通道内跑出负收益再回退。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-26\">二十六 · 配方参数：把 k 写成接受率与 batch 形状的函数</h3>\n<p>把上面的判断收拢成一条可执行的调参逻辑。给定当前滑动窗口接受率估计 $\\hat{a}$、每帧 token 数 $N_{\\text{tok}}$、Tensor Core 高效区间的 batch 下界 $B_{\\min}$ 与上界 $B_{\\max}$，k 的可行域由 batch 形状约束：</p>\n<div class=\"formula\">$$k\\in\\left[\\left\\lceil\\frac{B_{\\min}}{N_{\\text{tok}}}\\right\\rceil,\\ \\left\\lfloor\\frac{B_{\\max}}{N_{\\text{tok}}}\\right\\rfloor\\right]$$</div>\n<p>在这个区间内，再按加速比公式选使 $\\mathbb{E}[\\text{speedup}]$ 最大的 k，其中 $a_j$ 用 $\\hat{a}$ 的衰减模型代入。若区间为空——$N_{\\text{tok}}$ 大到 $B_{\\max}/N_{\\text{tok}}&lt;1$——说明该请求的帧 token 数已超出投机可用的 batch 空间，直接不走投机。若按 $\\hat{a}$ 算出的最优 k 落在区间下界以下，说明接受率太低、投机不划算，同样关闭。</p>\n<p>草稿步数与 k 联动：草稿步数决定草稿段串行前向的次数，k 决定验证 batch 大小。草稿步数过多会让草稿段成为关键路径瓶颈，过少则候选帧质量差、接受率低。配方上把草稿步数设为 k 的单调函数，k 大时草稿步数相应增加以维持候选质量，但总草稿前向时间不得超过单帧时延预算的一个固定比例——这个比例是配方的硬约束，超过就降 k。</p>\n<p>代价核算要落到三个量上：单帧时延（草稿段串行时间加验证段并行时间加回退重采样时间）、显存（双份权重加双份 KV 加验证 batch 激活）、带宽（验证 batch 的 GEMM 读取与 KV 读写）。三者中任何一个触顶，配方就要在该维度上收缩。具体例子：某请求类型 $N_{\\text{tok}}$ 偏大，batch 上界约束把 k 压到 2，此时加速比公式给出的收益有限，但单帧时延仍在 SLO 内，配方选择保留 k=2 而不是关闭投机——因为关闭后串行解码的时延更高。这个判断只能靠实测的时延曲线做，不能靠公式单独决定。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-27\">二十七 · 负载配方的工程落点</h3>\n<p>落点上最重要的一条：把“是否走投机”做成请求级的准入判断，而不是全局开关。准入判断的输入是请求类型标签、预估帧数、当前系统并发水位与显存水位；输出是走投机、走普通自回归、或走投机但限 k。这个判断在请求入队时做一次，在生成过程中按滑动窗口接受率复判，接受率跌破阈值就中途降 k 或退出投机。中途退出的代价是已写入 KV cache 的前缀要按目标模型口径校正——接受准则保证已接受前缀无偏，所以退出时不需要重算已输出帧，只需后续帧改走普通路径。</p>\n<p>第二条：并发上限与 k 的联动要写进调度器，不能留给运维拍。调度器在每次派发前检查 $\\text{并发}\\times k\\cdot N_{\\text{tok}}$ 是否超过当前档位的验证吞吐预算，超过就排队或降 k。这个检查的粒度是请求级，因为不同请求的 $N_{\\text{tok}}$ 与历史接受率不同，统一降 k 会误伤高接受率请求。</p>\n<p>第三条：长尾请求单独分档。超长请求的 KV 复制成本与验证 batch 溢出风险都最高，配方上给它们单独的显存预留与更小的 k 上界，或者在队列层面限制其并发。分档的依据是帧数分布的分位点，分档阈值随部署实测的显存水位调整。</p>\n<p>最后一条落在监测上：接受前缀长度、验证段 SM 利用率、单帧时延分位、显存水位四个指标要一起看。接受前缀长度下滑而 SM 利用率不降，是接受率塌陷的前兆；SM 利用率下滑而接受前缀长度正常，是 batch 形状塌陷；显存水位随帧数爬升而吞吐下降，是显存塌陷。三种塌陷的处置方向不同，混在一起看会调错参数。配方不是一组静态数字，是一套把负载形态映射到 k、并发、准入的规则，规则的有效性只能由这四个指标的联合走势来验证。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-28\">二十八 · 硬件档位：按目标模型显存加草稿余量切三档</h3>\n<p>部署配方第一步不是选框架，而是把显存账算清楚。投机解码在视频自回归里要同时驻留两套权重与两套KV：目标模型决定画质与分布，草稿模型决定提出速度。硬件档位因此不能按“单模型放得下”来划，而要按<strong>目标权重 + 草稿权重 + 双份KV峰值 + 验证batch激活</strong>四块之和来划。工程上切三档最实用：单卡档、单节点档、多节点档。</p>\n<p>单卡档（如单张B200/B300级显存）只容纳中小分辨率、短窗口的目标模型，草稿模型必须压到极低精度并共享部分层，KV用分页加按帧淘汰；这一档的瓶颈是显存容量而非带宽，验证batch往往被迫压到很小，Tensor Core利用率上不去，收益主要来自“草稿串行但便宜”。单节点档（GB200/GB300 NVL72内的一个托盘）是主战场：目标模型权重按FP8或NVFP4驻留，草稿模型独立权重但精度更低，双份KV分池管理，验证batch能做到几十到上百个token位置，落在MMA高效区间。多节点档只在长视频、高分辨率、目标模型本身已跨卡切分时出现，此时草稿模型要么与目标同拓扑切分，要么单独占一组卡，通信开销开始进入关键路径。</p>\n<p>判据可以写成一个显存约束：设目标权重为$W_t$、草稿权重为$W_d$、单帧KV为$K_f$、窗口帧数为$F$、验证batch为$B_v$，则单卡可行条件近似为</p>\n<div class=\"formula\">$$W_t+W_d+2\\cdot K_f\\cdot F+\\text{act}(B_v)\\le C_{\\text{HBM}}$$</div>\n<p>其中系数2就是双份KV的代价。举例：一个中等规模视频DiT目标模型用FP8驻留、草稿模型用NVFP4且层数减半，长视频窗口拉到数百帧时，$2K_fF$项会迅速超过两份权重之和——这正是长视频下“KV复制成本高”的具体形态。档位选择的工程判断是：先固定目标模型精度与窗口长度，再看剩余显存能否给草稿模型留出独立权重；若不能，就退到共享层或低分辨率草稿，而不是硬塞。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-29\">二十九 · 并行拓扑：草稿与目标不必同构</h3>\n<p>并行拓扑的核心问题是：草稿模型和目标模型的切分方式是否必须一致。答案是不必，但KV布局必须对齐。目标模型若因权重规模采用张量并行（TP）跨多卡，草稿模型通常小到可以单卡放下，此时草稿走单卡、目标走TP组，草稿产出的候选帧latent需要广播到TP组的每个rank，验证阶段各rank持有自己那份KV分片并行计算logits，接受判定在rank间做一次归约。这条路径的代价是每轮验证一次小规模all-gather加一次归约，延迟量级远小于一次完整前向，但轮数多时会累积。</p>\n<p>另一种拓扑是草稿与目标同TP度切分，好处是KV分片布局一致、候选latent无需重排，坏处是小草稿模型在TP下每卡计算量过小、通信占比上升。工程上按草稿模型单卡能否放下做二分：放得下就走“草稿单卡 + 目标TP”，放不下才同构切分。对NVL72这种NVLink 5域内的高带宽互连，跨卡广播的代价可以接受；跨节点则要避免每轮验证都做全局同步。</p>\n<p>验证batch的组织方式也属于拓扑决策。把$k$个候选帧拼成batch一次前向，等价于把验证batch设为$k\\cdot N_{\\text{tok}}$（$N_{\\text{tok}}$为每帧latent token数）。这个batch在TP组内被切分，每卡看到的是$k\\cdot N_{\\text{tok}}/\\text{TP}$。若这个数太小，MMA的M维填不满，Tensor Core空转；若太大，激活显存与KV写入带宽吃紧。可复现的做法是给每卡验证token数设一个下限（按目标模型hidden维度与MMA指令形状估算），由它反推$k$的上界，再让动态$k$在这个上界内浮动。</p>\n<p>具体例子：目标模型TP=4、每帧latent展开为若干token，若每卡高效区间要求验证token数不低于某阈值，则$k$的上界由该阈值乘TP再除以$N_{\\text{tok}}$得到；接受率高时$k$取上界，接受率跌到阈值以下时$k$收缩到1，退化为普通自回归，避免验证开销反超。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-30\">三十 · 量化方案：目标保分布，草稿保速度</h3>\n<p>量化在投机解码里不是统一决策，而是分工决策。目标模型承担无偏接受准则的分布基准，它的精度直接决定$p_{\\text{tgt}}$的形状；草稿模型只提供候选，精度低只影响接受率$a_j$，不影响最终输出分布。因此配方是：目标模型用FP8（注意力与GEMM）加关键层更高精度，草稿模型用NVFP4甚至更低，且草稿的低精度误差要被接受准则“过滤”掉——被拒绝的位置由目标模型重采样，错误不会传播。</p>\n<p>这里有一个容易踩的坑：接受准则比较的是两个模型的概率比，若草稿模型量化过激导致分布严重偏移，接受率会骤降，$k$再大也无用。可用事实明确指出草稿误差随$k$增大快速累积使接受率骤降，量化正是放大这一效应的因素之一。因此草稿量化要保留输出头与采样相关层的精度，把激进量化放在中间层与注意力投影上；目标模型的KV cache量化则要谨慎，KV精度影响$p_{\\text{tgt}}(y_i\\mid y_{&lt;i})$的长程一致性，长视频下KV量化误差会随窗口增长累积。</p>\n<p>代价侧写：目标模型FP8相对BF16把权重带宽减半，单步前向的内存带宽压力下降，这对“单步延迟受内存带宽限制”的自回归视频是直接收益；草稿模型NVFP4把草稿前向的权重读取压到最低，使草稿串行段更便宜。但量化引入的反量化开销与缩放因子管理会增加kernel复杂度，验证batch大时这部分被摊薄，batch小时反而显眼。工程判断是：验证batch落在高效区间时放心用低精度草稿；batch被迫缩小时，草稿精度不宜再降。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-31\">三十一 · KV策略：双份KV的分池、复制与淘汰</h3>\n<p>双份KV是本算法最硬的显存代价。目标模型KV是权威状态，草稿模型KV是草稿自回归的上下文。两者在每轮验证后需要同步：接受前缀写入目标KV，草稿KV也要跟进到相同前缀，否则下一轮草稿的起点就错了。同步方式有两种：复制（把目标KV的前缀段拷给草稿）与重算（草稿用自己的权重对接受前缀重跑一遍前向重建KV）。复制省算力但吃带宽与显存，重算省显存但吃草稿前向时间。长视频下前缀段很长，复制的带宽代价按窗口线性增长，重算的代价按前缀长度线性增长，二者都不便宜。</p>\n<p>可复现的策略是分池加分层淘汰：目标KV按帧分页驻留，超出窗口的旧帧按重要性淘汰或转出到更低层级存储；草稿KV只保留最近若干帧的滑动窗口，因为草稿只需要局部上下文提出候选，不需要完整长程历史。这样草稿KV的显存占用与窗口长度解耦，双份KV的峰值被压到“目标全窗口 + 草稿短窗口”。代价是草稿在长程一致性上弱于目标，接受率在需要长程记忆的帧上会下降，动态$k$会感知到并收缩。</p>\n<p>另一个策略点是验证阶段的KV写入。目标模型并行验证$k$个候选时，会为每个候选位置算出KV，但只有接受前缀的KV是有效的，被拒绝位置的KV必须丢弃。若框架把验证KV直接写进cache再回滚，会产生无效写入带宽；更干净的做法是验证时把KV写到临时缓冲，接受判定后再提交前缀段。这一步的代价是一次额外的拷贝，但避免了长视频下反复回滚造成的cache碎片。</p>\n<p>具体例子：一个长视频流式请求，目标KV按帧分页、窗口数百帧，草稿KV只留最近十余帧；每轮验证后只把接受前缀对应的分页提交到目标池，草稿池按滑动窗口截断。这样双份KV的峰值主要由目标池决定，草稿池成为常数项，显存规划从“两倍窗口”变成“一倍窗口加常数”。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-32\">三十二 · 调度参数：动态k、草稿步数与SLO绑定</h3>\n<p>调度参数里最关键的是$k$与草稿步数，二者都随接受率动态调整。可用事实给出的期望加速公式为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>分子是接受带来的有效步数增益，分母是草稿开销相对目标单步开销的放大。$a_j$随$j$衰减，所以$k$存在最优点：$k$增大时分子增长放缓、分母线性增长，越过最优点后加速比下降。工程上不解析求最优，而是用接受率的滑动统计做反馈控制：连续若干轮接受率高于阈值就增大$k$，低于阈值就收缩$k$并减少草稿步数（草稿用更少步数换更快提出，代价是候选质量下降、接受率进一步下降，所以收缩要同步）。</p>\n<p>调度还要与SLO绑定。在线视频请求的SLO以单帧时延为主，调度器应把$k$的选择目标设为“单帧时延不超过预算”，而不是“吞吐最大”。当验证batch因$k$增大而超出Tensor Core高效区间时，单帧时延反而上升，此时应优先保时延、牺牲部分吞吐。批调度层面，连续批处理把多个请求的验证batch拼在一起能填满MMA，但不同请求的接受率不同，拼批会让高接受率请求被低接受率请求拖累；可复现的做法是按接受率分桶，同桶请求拼批，桶内$k$一致。</p>\n<p>具体例子：一个在线服务同时处理多个自回归视频请求，调度器为每个请求维护接受率估计，按估计值分到高、中、低三桶；高桶用大$k$、低桶用$k=1$退化路径；每桶的验证batch单独拼批以落在高效区间。当某请求接受率从高桶跌到低桶，它被迁移，避免拖累高桶的batch形状。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-33\">三十三 · 可复现的配置思路：从显存账到参数表</h3>\n<p>把上述决策串成一条可复现的路径，顺序是：定窗口与分辨率 → 定目标模型精度与并行度 → 算剩余显存 → 定草稿模型规模与精度 → 定KV分池策略 → 定$k$的上界与动态规则 → 定分桶与SLO约束。每一步都有明确的判据，不依赖调参直觉。</p>\n<p>第一步，按业务SLO定最大窗口帧数与分辨率，这决定$K_f\\cdot F$的量级。第二步，目标模型精度选FP8、并行度按权重能否单节点放下选TP度，得到$W_t$与每卡KV分片。第三步，用第一节的显存不等式算剩余容量，若剩余容量不足以放独立草稿权重，则草稿改为共享层或低分辨率版本；若足够，草稿选NVFP4并保留输出头精度。第四步，KV分池：目标池全窗口分页，草稿池短滑动窗口，验证KV走临时缓冲后提交。第五步，按每卡验证token数下限反推$k$上界，设定接受率高低两个阈值与对应的$k$档位。第六步，按接受率分桶拼批，SLO以单帧时延为约束，吞吐为次优目标。</p>\n<p>这套配置的失败模式要提前埋检测点：接受率连续下降说明草稿误差累积或量化过激，触发$k$收缩与草稿精度复核；显存峰值逼近上限说明双份KV或验证激活超预算，触发窗口截断或草稿池进一步缩小；验证batch形状偏离高效区间说明$k$与TP度不匹配，触发$k$上界重算。三个检测点分别对应可用事实列出的三条失败模式，配方的作用是把它们变成可观测的运行时信号，而不是事后归因。</p>\n<p>最后的工程判断落在一点：投机解码在视频自回归里的收益不是常数，它由接受率与验证batch形状共同决定，而这两者都被显存预算约束。配置思路的本质是把“双份权重与双份KV”的显存代价先付清，再在剩余空间里把$k$和batch形状调到Tensor Core高效区间；显存账算不清时，任何调度参数都是在噪声上做优化。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-34\">三十四 · 验证批的算术：k 放大的是激活还是权重</h3>\n<p>把 k 个候选帧 latent 拼成 batch 走一次前向，表面上只是把 GEMM 的 M 维从 1 抬到 k·N<sub>tok</sub>，但代价结构并不对称。目标模型单步解码在 batch=1 时是彻底的权重带宽绑定：每生成一个 token 要把全部权重从 HBM 读一遍，Tensor Core 大部分时间在等数据。验证阶段 batch 抬到 k·N<sub>tok</sub> 后，同一份权重只读一次却服务 k·N<sub>tok</sub> 行激活，算术强度近似按 k·N<sub>tok</sub> 线性上升，直到撞上 Tensor Core 的算力天花板或 TMEM/SMEM 容量。这就是收益的来源，也是上限的来源。</p>\n<p>把单次验证的时间写成两段之和：</p>\n<div class=\"formula\">$$T_{\\text{verify}}\\approx\\underbrace{\\frac{W}{B_{\\text{HBM}}}}_{\\text{权重读取}}+\\underbrace{\\frac{kN_{\\text{tok}}\\cdot W}{F_{\\text{peak}}\\cdot\\eta(kN_{\\text{tok}})}}_{\\text{算力项}},\\quad \\eta(\\cdot)\\in(0,1]$$</div>\n<p>其中 η 是随 batch 变化的 Tensor Core 利用率。k 小时第二项可忽略，T<sub>verify</sub> 与 k 几乎无关——这正是投机解码“免费”的区间；k 越过某个阈值后第二项开始主导，且 η 随 batch 继续增大而边际递减（tcgen05 的 MMA 形状、TMEM 驻留的累加器与操作数分块都会限制大 M 的效率）。工程判断因此不是“k 越大越好”，而是把 k·N<sub>tok</sub> 钉在 η 的拐点附近：低于拐点浪费了权重读取的固定成本，高于拐点则每多一个候选都在买递减的算力。</p>\n<p>具体到视频：一帧 latent 的 token 数 N<sub>tok</sub> 远大于文本的一个 token，k=4 时验证 batch 可能已经是四位数 token。这意味着视频投机解码的“高效区间”比文本投机解码窄得多——文本里 k 从 4 加到 8 常常还在免费区，视频里同样的加法可能直接把验证推进算力绑定区。调 k 的粒度必须按 N<sub>tok</sub> 归一，而不是按帧数直觉。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-35\">三十五 · 双份 KV：长视频下最先崩的那堵墙</h3>\n<p>草稿模型与目标模型各持一份 KV cache。文本场景里 KV 是每 token 几个 KB 量级，双份尚可承受；视频自回归的 KV 随帧数线性增长，且每帧的 latent token 数量级更高，双份 KV 的绝对占用很快从“余量”变成“主项”。更麻烦的是草稿模型若采用低分辨率或少步蒸馏，其 KV 的语义空间与目标模型并不对齐，不能共享同一份 cache，只能各写各的——这不是实现偷懒，是分布不一致的必然结果。</p>\n<p>设目标模型 KV 每帧占用 S<sub>tgt</sub>、草稿模型 S<sub>dr</sub>，生成长度 L 帧，则显存约束为：</p>\n<div class=\"formula\">$$W_{\\text{tgt}}+W_{\\text{dr}}+L\\,(S_{\\text{tgt}}+S_{\\text{dr}})+A_{\\text{verify}}(kN_{\\text{tok}})\\le C_{\\text{HBM}}$$</div>\n<p>三项里前两项是常数，第三项随 L 线性爬升，第四项是验证激活的瞬时峰值。规模上去以后先崩的通常不是权重——权重是规划时就知道的——而是第三项：L 增长到某个点，KV 把留给验证激活的空间挤没，于是要么降 k（收益消失），要么把 KV 换出到主机内存（PCIe 带宽成为新的串行瓶颈，单帧时延被换入换出主导）。这就是长视频投机解码的典型死法：不是算不动，是放不下。</p>\n<p>工程上的缓解方向有三条，各有代价。其一是草稿模型只保留最近窗口的 KV、更早的帧用压缩表示，代价是草稿质量在长程上退化、接受率下滑；其二是把草稿 KV 放到更低精度（这与本模块其他条目讲的 2bit KV 量化是不同层面的问题，此处只作指路），代价是草稿分布偏移进一步压低接受率；其三是草稿与目标共享一份 KV、草稿只读不写，代价是草稿无法反映自己已提出的候选帧，k 大时误差累积更快。三条都在“省显存”和“保接受率”之间做交换，没有免费选项。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-36\">三十六 · 通信：验证批与分离式部署的耦合</h3>\n<p>当目标模型大到需要跨卡张量并行、或按预填/解码分离部署时，验证阶段的通信量随 k·N<sub>tok</sub> 放大。张量并行下每层有一次 all-reduce，其消息大小与激活的 token 数成正比：batch=1 时 all-reduce 是延迟绑定的小消息，k·N<sub>tok</sub> 行激活时它变成带宽绑定的大消息。NVLink 5 的带宽足以吞下这些消息，但“足以”不等于“免费”——验证步的通信时间会从单步延迟的零头变成可观测的分量，尤其在层数深、TP 度大的配置下，每层一次 all-reduce 的累加不可忽略。</p>\n<p>分离式部署把问题换了个形状：草稿模型与目标模型若不在同一组 GPU 上，候选 latent 与接受结果要在预填/解码节点间往返。k 个候选的传输量是 k·N<sub>tok</sub>·d·sizeof(dtype)，用 NVFP4 或 FP8 传输能把这个量压下去，但压缩引入的数值扰动会轻微改变接受判定——接受准则比较的是分布比值，量化后的 logits 让比值出现偏差，边界样本上的接受/拒绝会翻转。这类翻转不破坏无偏性（准则仍在目标分布下成立），但会让实测接受率与理论值出现系统性偏移，调 k 的自适应逻辑若按理论接受率建模就会失准。</p>\n<p>尾延迟在这里被放大：验证步是一个同步屏障，k·N<sub>tok</sub> 行里最慢的那条路径（某个被拒绝位置的额外重采样、某次跨节点往返的排队）决定整步完成时间。批越大，长尾样本被纳入同一批的概率越高，P99 与 P50 的差距随之拉开。视频在线请求的 SLO 以单帧时延为主，尾延迟恶化直接表现为帧率抖动，而不是平均吞吐下降——这是容量规划时最容易漏掉的一项。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-37\">三十七 · 功耗与热：验证批把能效曲线掰弯</h3>\n<p>batch=1 的解码是低利用率、低功耗的状态：SM 大量时间在等 HBM，功耗落在 idle 与轻载之间。验证批把 SM 拉满，功耗曲线陡升。对单卡无所谓，对 GB200/GB300 NVL72 机柜则是另一回事：整柜的功率预算是固定的，验证步的瞬时功耗峰值会顶到机柜上限，触发降频，而降频又反过来拉长验证步时间、压低 η。这是一个正反馈的恶化环：k 越大→验证批越大→功耗峰值越高→降频越深→η 越低→为了维持时延又想把 k 调更大。</p>\n<p>破解点在占空比而非峰值。草稿阶段是串行、低占用的，验证阶段是并行、高占用的，两者交替形成天然的功率脉冲。把多个请求的验证步错峰排布（连续批处理天然具备这个能力，但需要调度器显式考虑功率而非只考虑显存和算力），可以把峰值削平，让机柜稳定运行在功率预算之下而不触发降频。代价是调度复杂度上升，且错峰会拉长单个请求的完成时间——又是一个吞吐与尾延迟的交换。</p>\n<p>能效的另一个角度是每帧焦耳数。验证批提高了单次前向的算术强度，单位算力的能耗下降，但总能耗取决于接受率：接受率低时，被拒绝的候选白算了一遍，这些算力对应的能耗是纯浪费。所以功耗优化的真正杠杆不在内核，而在接受率——把草稿模型的质量提上去，比任何功率调度技巧都更直接。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-38\">三十八 · 规模上去以后，崩溃的顺序</h3>\n<p>把规模逐步推大，各资源的紧张顺序是有规律的，识别这个顺序决定了扩容时先加什么。</p>\n<table class=\"mini\"><thead><tr><th>规模阶段</th><th>先撞到的约束</th><th>表现</th><th>缓解手段与代价</th></tr></thead><tbody><tr><td>单卡、短序列</td><td>权重带宽</td><td>单步延迟高但稳定，k 几乎免费</td><td>加大 k，代价是草稿误差累积</td></tr><tr><td>单卡、长视频</td><td>双份 KV 显存</td><td>k 被迫收缩，收益消失；或换出导致时延尖峰</td><td>窗口化草稿 KV、低精度草稿 KV，代价是接受率下滑</td></tr><tr><td>多卡 TP</td><td>验证步通信</td><td>all-reduce 从零头变主项，P99 拉长</td><td>限制 TP 度、压缩传输精度，代价是接受判定偏移</td></tr><tr><td>机柜级</td><td>功率峰值与降频</td><td>η 下降，时延抖动，形成恶化环</td><td>验证步错峰调度，代价是单请求完成时间变长</td></tr><tr><td>高并发在线</td><td>接受率统计的稳定性</td><td>动态 k 的反馈环震荡，吞吐不稳</td><td>加阻尼、按窗口平滑接受率，代价是响应变慢</td></tr></tbody></table>\n<p>这张表的读法是：每一行都对应一个具体的资源项和一个具体的失败模式，扩容时按行从上往下检查，先崩的那一项就是瓶颈。多数部署在第二行就停下——长视频的双份 KV 是视频投机解码最普遍的上限，而不是算力。这也解释了为什么本算法的适用边界写得那么保守：规模上限受双份权重与 KV 显存约束，接受率低或长视频 KV 复制成本高时收益消失。</p>\n<p>最后一行值得单独说：动态 k 是一个闭环控制，接受率的估计来自最近若干步的实测。高并发下每个请求的接受率样本很少，估计噪声大，k 会跟着噪声上下跳；k 一跳，验证 batch 就跳，η 跟着跳，时延抖动被放大。控制环的阻尼必须与请求的采样窗口匹配，否则系统会在“k 太大→接受率低→k 缩小→接受率高→k 又变大”之间周期性震荡。这是纯工程问题，与算法本身无关，但它是规模上去以后最隐蔽的崩溃点——资源都没满，吞吐却在抖。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-39\">三十九 · 规模放大后的五道坎：显存、带宽、通信、功耗与尾延迟</h3>\n<p>把投机解码从单卡小 batch 推到 NVL72 级别的在线服务，第一个崩的几乎总是显存而不是算力。草稿模型与目标模型双份权重只是固定开销，真正随规模线性膨胀的是 KV：验证阶段要把 k 个候选帧拼成一个 batch 一次性前向，这些候选各自带着从当前 KV cache 派生出的上下文副本，长视频下 KV 复制成本按候选数放大。设单帧 KV 占用为 $S_{\\text{kv}}$、并发请求数为 $N$、候选数为 $k$，则验证瞬间的 KV 峰值近似 $N\\cdot S_{\\text{kv}}\\cdot(1+k)$，而稳态只占 $N\\cdot S_{\\text{kv}}$。这条式子决定了 k 的上限不是由接受率单独决定，而是由显存余量除以并发数决定；一旦越界，调度器只能降 k 或降并发，两者都直接砍吞吐。</p>\n<p>第二道坎是带宽与采样链的耦合。自回归视频解码的单步延迟本就受内存带宽限制，草稿模型虽然轻量，却仍要逐帧串行走完 k 步，每一步都要读自己的权重与 KV；这段串行时间无法被目标模型的并行验证掩盖，只能与之串联。于是端到端单帧时延近似 $T\\approx k\\cdot t_{\\text{draft}}+t_{\\text{verify}}(k\\cdot N_{\\text{tok}})$，其中 $t_{\\text{verify}}$ 随验证 batch 增大而摊薄但不会趋零。当接受率 $a_j$ 随 j 快速衰减时，有效推进帧数远小于 k，$k\\cdot t_{\\text{draft}}$ 却照付，收益被草稿的串行开销吃掉——这正是公式 $\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$ 在 $a_j$ 骤降时迅速跌破 1 的物理含义。</p>\n<p>第三、四道坎是通信与功耗，它们在多卡张量并行下才显形。目标模型的验证前向若切分到多卡，k 个候选拼成的 batch 会让每卡的 all-reduce 消息尺寸随 k 放大，通信量与验证 batch 同阶增长；草稿模型若也做并行，则多出一条独立的通信链，两条链在同一 NVLink 域上争带宽。功耗侧，验证 batch 拉大提高 Tensor Core 利用率的同时也把瞬时功耗推高，机柜功率封顶时反而限制 k 的上界。第五道坎是尾延迟：动态 k 依赖近期接受率估计，估计滞后会让个别请求在帧间相关性变弱（镜头切换、快速运动）时接受率骤降，验证开销反超，P99 单帧时延出现尖峰，而均值吞吐看起来仍然正常。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的资源</th><th>工程对策</th></tr></thead><tbody><tr><td>并发 N 上升</td><td>KV 显存（$(1+k)$ 倍峰值）</td><td>按显存余量反推 k 上限，候选 KV 用分页/共享基座</td></tr><tr><td>k 增大</td><td>草稿串行时延、验证 batch 越界</td><td>接受率自适应收缩 k，锁在 Tensor Core 高效区间</td></tr><tr><td>长视频</td><td>KV 复制带宽</td><td>候选共享前缀 KV，仅复制分歧段</td></tr><tr><td>多卡 TP</td><td>all-reduce 带宽、功耗封顶</td><td>验证 batch 与 TP 度联合定档</td></tr></tbody></table>\n<p>工程判断因此很直接：这套方案的规模上限由“双份权重加 $(1+k)$ 倍 KV 峰值”与“草稿串行时延不可掩盖”两条硬约束共同划定。帧间相关性强、镜头稳定、草稿误差可控时，k 可以取大、验证 batch 落在高效区间，收益成立；一旦进入长视频、高并发、快切镜头的混合负载，先失效的是显存与尾延迟，而不是接受准则本身——无偏性始终成立，失效的是经济性。容量规划应按目标模型显存加草稿模型余量定硬件档位，并把 k 与草稿步数的自适应收缩做进调度器，而不是留给请求侧碰运气。</p>\n<h3 id=\"alg-spec-decode-video-ar-sec-40\">四十 · 精度漂移：接受率骤降的数值根因</h3>\n<p>视频投机解码的接受准则本身是无偏的，但无偏的前提是草稿分布与目标分布都被正确计算。工程上最先崩的往往不是算法，而是数值：草稿模型若跑低精度（少步蒸馏权重配 FP8 甚至 NVFP4 激活），目标模型跑 BF16 或 FP8，两者在同一位置上的 logits 差异会被接受准则放大。接受准则要求逐位置比较 $\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u$，这个比值在概率接近零的尾部 token 上对舍入误差极其敏感——草稿给出 $10^{-4}$、目标给出 $10^{-6}$，比值就是 100 倍偏差，直接判拒绝。视频 latent token 的分布比文本更尖（帧间强相关导致大量位置概率集中在少数候选），尾部更薄，舍入噪声的相对影响更大。</p>\n<p>诊断手段是分层埋点：在验证阶段记录每个位置的 $\\log p_{\\text{tgt}}-\\log p_{\\text{draft}}$ 差值分布，而不是只看整体接受率。若差值分布的中位数随 k 增大而系统性偏移，说明草稿模型的低精度累积误差在起作用；若只有长尾位置偏移，则是量化 scale 在极端激活上的截断。前者要收紧草稿精度或缩短草稿步数，后者要检查草稿模型输出层的 per-channel scale 是否覆盖了视频 latent 的动态范围。代价上，精度提升直接吃掉收益：草稿从 FP8 升到 BF16，草稿前向的显存带宽需求翻倍，而草稿串行步数不变，端到端时延里草稿部分线性变长。一个具体判断是：当草稿精度升级带来的接受率提升不足以抵消草稿单步时延的增加时，应改回低精度但收缩 k，让验证 batch 变小、拒绝回退次数变少。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-41\">四十一 · OOM：双份 KV 在长视频下的挤压</h3>\n<p>显存失败在视频投机解码里几乎必然出现，因为结构上就有两份权重加两份 KV。目标模型的 KV cache 随视频长度线性增长，草稿模型为了与目标对齐上下文，通常要维护一份结构相同（层数更少、维度更小）的 KV，长视频下这份复制的绝对量并不小。更隐蔽的是验证阶段的临时激活：k 个候选帧 latent 拼成 batch 一次前向，验证 batch 为 $k\\cdot N_{\\text{tok}}$，中间激活与 attention 工作区随 k 线性膨胀，这部分是瞬时峰值而非稳态占用，监控稳态显存根本看不到。</p>\n<p>诊断要区分三类 OOM：稳态权重+KV 超限、验证瞬时峰值超限、碎片化导致的分配失败。第一类看长期驻留曲线，第二类要在验证前向的入口和出口打点记录 allocator 的 reserved 与 allocated 差值，第三类看最大空闲块是否小于单次验证所需的连续显存。工程对策按代价排序：先降 k（直接缩小验证 batch 与瞬时激活，代价是接受前缀变短、串行回退增多）；再把草稿 KV 改为按需重算而非常驻（代价是草稿前向变慢，因为要重跑上下文）；最后才动目标模型 KV 的量化或分页。分页 KV 在视频场景要小心，帧 latent 的访问模式是长距离跨帧注意力，页表命中率低会引入额外延迟。一个具体例子：长视频分段生成时，若每段都保留完整历史 KV，段数增加后草稿 KV 复制成本按段数累积，此时应在段边界做 KV 压缩或只保留关键帧的 KV，把草稿模型的上下文裁剪到最近若干帧加稀疏关键帧。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-42\">四十二 · 批抖动与路由不均：验证 batch 偏离高效区间</h3>\n<p>Blackwell 的 Tensor Core 在验证阶段吃的是批处理 GEMM，效率取决于 $k\\cdot N_{\\text{tok}}$ 是否落在高效区间。批抖动来自两个方向：请求到达率波动导致并发请求数变化，以及每个请求的接受率波动导致动态 k 调整。前者是外部负载问题，后者是内部控制环问题。当多个请求共享一个验证 batch 时，各请求的接受率不同，动态 k 会给出不同的候选数，拼 batch 时短请求填充浪费、长请求拉高瞬时激活，GEMM 的 M 维被不规则切分，效率掉到高效区间之外。</p>\n<p>路由不均出现在分离式部署里：草稿节点与目标节点之间的请求分配若按请求数而非按 token 数或按预期验证 batch 大小来路由，会出现某些目标节点验证 batch 长期偏小（GEMM 效率低、时延高）而另一些长期偏大（瞬时显存吃紧、排队）。诊断指标应是每个目标节点上的验证 batch 实际大小分布，而不是请求计数。控制手段是把动态 k 的调整放到请求级而非全局级，并在拼 batch 时按 $k\\cdot N_{\\text{tok}}$ 做装箱，把相近大小的候选组到一起，减少填充。代价是装箱本身引入调度延迟，且装箱粒度越细、调度开销越大；工程上取一个固定桶宽（例如按 Tensor Core 高效区间的下沿对齐），让桶内差异由硬件吸收。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-43\">四十三 · 尾延迟尖刺：拒绝回退的串行放大</h3>\n<p>投机解码的时延分布不是单峰的。接受前缀长时，一次验证出多帧，单步时延低；一旦首个位置就拒绝，验证 batch 的全部计算作废，目标模型要重采样该位置，然后草稿模型重新起草，形成一次“验证—拒绝—重采样—再起草”的串行链。视频场景里这种尖刺被放大，因为拒绝位置之后丢弃的候选帧 latent 可能已经消耗了可观的草稿计算，且重采样后帧间一致性要靠目标模型重新建立，KV 写入模式也被打断。</p>\n<p>尾延迟的诊断不能只看平均接受率，要看接受前缀长度 $m$ 的分布，尤其是 $m=0$ 或 $m=1$ 的比例。这个比例升高时，端到端时延的 P99 会显著恶化，因为每次短前缀都触发完整的回退链。公式上，期望加速比 $\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$ 里分子对低 $a_j$ 极其敏感：$a_1$ 从 0.9 掉到 0.6，分子里所有高阶项同时缩水，而分母的草稿成本不变，加速比可能跌破 1。工程判断是给 $a_1$ 设硬阈值：低于阈值时直接跳过投机、走目标模型单步解码，把尾延迟压回基线，而不是让回退链反复触发。代价是跳过投机后吞吐下降，但在 SLO 以单帧时延为主的在线视频请求里，尾延迟优先于平均吞吐。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-44\">四十四 · 监控与回滚：把失败模式变成可观测信号</h3>\n<p>监控体系要覆盖四层信号，每层对应一类失败模式。第一层是接受统计：逐位置的 $a_j$、前缀长度分布、$\\log p$ 差值分布，用于精度漂移与尾延迟。第二层是显存：稳态驻留、验证前向瞬时峰值、最大空闲块，用于 OOM 三类区分。第三层是批形态：验证 batch 实际大小直方图、装箱填充率、每节点 GEMM 效率代理指标（如验证前向的实际耗时与理论耗时之比），用于批抖动与路由不均。第四层是端到端：单帧时延 P50/P99、拒绝回退链触发次数、跳过投机比例。</p>\n<p>回滚要分级且自动化。一级回滚是参数级：接受率低于阈值时收缩 k 与草稿步数，这是运行时的连续动作，不重启服务。二级回滚是路径级：$a_1$ 持续低于硬阈值时关闭投机路径，全部走目标模型单步解码，保留草稿模型驻留但不参与前向，避免反复加载权重带来的显存抖动。三级回滚是精度级：草稿精度升级后若接受率未达预期且时延恶化，回退到原精度配置。四级是部署级：路由不均持续时把请求分配从按请求数改为按预期验证 batch 大小，必要时把草稿与目标重新绑定到同一节点以减少跨节点 KV 传输。</p>\n<p>回滚的触发条件必须绑定具体机制而非笼统的“异常”。例如 OOM 触发二级回滚前，要先确认是验证瞬时峰值还是稳态超限：瞬时峰值超限降 k 即可，稳态超限要动 KV 驻留策略，两者回滚动作不同。尾延迟尖刺触发路径级回滚前，要确认 $m=0$ 比例升高是精度问题还是负载问题：精度问题回滚精度，负载问题回滚 k。一个具体工程判断是：所有回滚动作都记录触发时的四层信号快照，因为视频投机解码的失败模式会互相伪装——OOM 降 k 后接受率下降被误读为精度问题，实际是 k 变小导致验证 batch 偏离高效区间、单步时延上升。监控的价值不在于报警，而在于让每次回滚都能归因到唯一机制。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-45\">四十五 · 失效边界：接受率塌陷、显存挤压与批形漂移的联锁诊断</h3>\n<p>这套方案最危险的失效不是单点报错，而是三个量互相耦合下滑：接受率 $a_j$ 随草稿步数 $k$ 增大而快速衰减，验证开销按 $k\\cdot N_{\\text{tok}}$ 线性膨胀，一旦期望加速比公式中的分子（接受前缀长度）追不上分母（验证批成本），时延就会不降反升。诊断上要把“每帧有效接受长度”$\\bar m$ 与“验证批填充率”分开采集：前者反映草稿模型对帧间冗余的拟合质量，后者反映 $k$ 是否仍落在 Tensor Core 高效区间。若 $\\bar m$ 连续下滑而填充率仍高，说明草稿误差在累积而非批形问题；若 $\\bar m$ 稳定但单帧时延尖刺，则应先怀疑验证批被拉长到高效区间之外，此时按接受率收缩 $k$ 比调草稿步数更直接。</p>\n<p>显存侧要单独建一条水位线：草稿与目标双份权重之外，长视频的 KV 复制是隐性放大器——每接受一段前缀就要把对应 KV 写入目标侧，被拒绝候选的 KV 则要丢弃或回滚。工程上应把“草稿 KV 峰值 + 目标 KV 峰值 + 验证批激活”三者之和作为准入判据，而不是按单模型显存规划硬件档位。OOM 往往不在稳态出现，而在长视频尾段 KV 线性增长叠加一次大 $k$ 验证批时触发，因此监控要按帧序号记录 KV 占用斜率，斜率突变即预警。</p>\n<p>路由不均与尾延迟尖刺常来自同一根源：连续批处理把不同接受率的请求混在一批，高接受率请求快速吐出、低接受率请求反复回退重采样，导致批内 token 数抖动，调度器为填满批而拉大 $k$，反过来压低整体接受率。可用的判据是把批内方差纳入调度：当某请求的滚动接受率低于阈值即降级为纯目标模型串行路径（放弃投机），并把它移出验证批。回滚策略应分级——先缩 $k$ 与草稿步数，再关投机走目标模型直解，最后才降分辨率或减帧；每级都要以单帧时延 SLO 为触发条件，且回滚后保留接受率统计用于恢复判定。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>观测指标</th><th>处置</th></tr></thead><tbody><tr><td>时延不降反升</td><td>接受率塌陷</td><td>$\\bar m$ 下滑、验证批成本占比升</td><td>收缩 $k$、减草稿步数</td></tr><tr><td>OOM 于长视频尾段</td><td>双份 KV 复制</td><td>KV 占用斜率、候选 KV 峰值</td><td>限前缀长度、分级回滚</td></tr><tr><td>尾延迟尖刺</td><td>批形漂移/路由不均</td><td>批内 token 方差、填充率</td><td>低接受率请求移出验证批</td></tr></tbody></table>\n<h3 id=\"alg-spec-decode-video-ar-sec-46\">四十六 · 对照维度：先分清“改分布”与“保分布”</h3>\n<p>把自回归视频投机解码放进同族算法里比较，第一步不是比速度，而是比它是否改变了采样分布。少步蒸馏把多步采样链压缩成少数几步，等价于用一个新分布 $q_{\\text{distill}}$ 替代目标分布 $p_{\\text{tgt}}$，收益来自采样链长度本身缩短，代价是分布偏移不可逆、需要重新训练；轨迹感知缓存复用复用历史中间量，改变的是计算图上的重复计算，分布仍由原模型决定，但对帧间差异大的片段复用命中率下降；动态稀疏时空注意力削减注意力计算量，属于近似计算，稀疏模式选错时质量损失直接体现在帧间一致性上。投机解码的位置不同：它保持 $p_{\\text{tgt}}$ 不变，只把“串行解码”重排为“草稿串行 + 验证并行”，接受准则</p>\n<div class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</div>\n<p>保证被接受前缀的联合分布与目标模型逐位置一致。因此选型的第一条判据是：质量预算是否允许分布偏移。允许偏移且能承担蒸馏训练成本，少步蒸馏的收益最直接；不允许偏移又必须提速，投机解码是唯一不动分布的选项。这条判据决定了后面所有代价比较的前提——投机解码的显存与验证开销，本质是为“无偏”付的税。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-47\">四十七 · 决策表：五类相邻算法的适用条件</h3>\n<p>下表把本卷涉及的相邻手段按“改什么、保不保分布、主要代价、失效条件”四列对照，用于工程选型时逐行排除。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>改动对象</th><th>分布</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody>\n<tr><td>自回归视频投机解码</td><td>解码调度（串行→草稿串行+验证并行）</td><td>保持无偏</td><td>双份权重与KV、验证batch</td><td>接受率低、长视频KV复制挤爆显存</td></tr>\n<tr><td>少步蒸馏采样</td><td>采样链长度</td><td>偏移，需重训</td><td>训练成本、质量上限</td><td>目标分布复杂、蒸馏容量不足</td></tr>\n<tr><td>轨迹感知缓存复用</td><td>重复计算复用</td><td>保持</td><td>缓存显存、命中率</td><td>帧间差异大、轨迹漂移</td></tr>\n<tr><td>动态稀疏时空注意力</td><td>注意力计算量</td><td>近似</td><td>稀疏模式选择开销</td><td>稀疏模式与运动不匹配</td></tr>\n<tr><td>NVFP4/FP8量化推理</td><td>数值精度</td><td>近似（可控）</td><td>量化误差、校准</td><td>激活离群值大、精度敏感层</td></tr>\n</tbody></table>\n<p>读表方式：前两列决定能不能用，后两列决定用了之后会不会翻车。投机解码与缓存复用、量化可以叠加——量化压低单次前向的带宽成本，缓存复用减少重复前向，投机解码减少串行步数，三者作用在不同层面，不冲突；但与少步蒸馏叠加时要小心，蒸馏后的草稿模型若已偏离目标分布，接受率会被系统性压低，验证开销反超收益。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-48\">四十八 · 收益公式下的选型算术</h3>\n<p>把候选方案放进同一个收益式子里比较，可以避免“看起来都能提速”的错觉。投机解码的期望加速为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</div>\n<p>分子是每个验证周期实际产出的token数期望，分母是草稿成本与目标验证成本的加权。选型时三个量必须同时估：接受率序列 $a_j$ 随 $j$ 衰减的速度、草稿单步成本与目标单步成本之比 $c_{\\text{draft}}/c_{\\text{target}}$、以及验证batch $k\\cdot N_{\\text{tok}}$ 是否落在Tensor Core高效区间。举例：若草稿模型是低分辨率少步版本，$c_{\\text{draft}}/c_{\\text{target}}$ 可以压得很低，但视频帧间相关性强并不等于草稿误差不累积——$a_j$ 随 $j$ 快速衰减时，分子趋近于 $1+a_1$，分母却随 $k$ 线性增长，加速比跌破1。此时正确动作不是加大 $k$，而是按接受率自适应收缩 $k$ 与草稿步数，把验证batch维持在高效区间。相对地，缓存复用的收益不依赖接受率，只依赖命中率，命中率高的长镜头片段里它更稳；稀疏注意力的收益与稀疏度线性相关，但质量风险不可逆。三者对比的结论是：投机解码的收益是条件收益，条件就是接受率可控。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-49\">四十九 · 显存与带宽：双份KV是选型的分水岭</h3>\n<p>视频场景与文本投机解码的关键差别在KV。文本里KV规模有限，双份KV通常可接受；长视频自回归生成中，KV cache随帧数线性增长，草稿模型若复制一份KV，显存占用直接翻倍，长视频下KV复制成本高到足以让方案不可行。选型时的硬判据是：目标模型权重加草稿模型权重加双份KV，是否在单卡或单节点显存预算内留有余量。若余量不足，优先考虑不引入第二套权重的方案——缓存复用只增加缓存条目、量化只改变数值格式，都不需要第二份KV。反过来，若显存充裕而单帧时延是SLO瓶颈，投机解码的验证并行正好把串行链路上的带宽等待转成批处理GEMM的吞吐。这里还有一个带宽视角：草稿模型每步仍要读自己的权重与KV，若草稿太小、每步读的量不足以喂满HBM带宽，草稿串行段本身就成为新的瓶颈，$c_{\\text{draft}}$ 降不下去，收益式分母改善有限。因此草稿模型的选型不是“越小越好”，而是“小到能压低单步成本、又不至于让草稿段变成带宽空转”。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-50\">五十 · 组合与排除：工程判断落在哪一层</h3>\n<p>实际部署里很少只用一种手段，选型要回答“叠加顺序”。一个可操作的判断顺序是：先看质量预算是否允许分布偏移，允许则少步蒸馏优先，不允许则进入下一步；再看单帧时延瓶颈是否在串行采样链，若是则投机解码，若瓶颈在注意力计算量则稀疏注意力，若瓶颈在重复前向则缓存复用；最后看显存余量能否容纳双份权重与KV，不能则退回量化与缓存复用组合。这个顺序的理由是代价的可逆性：量化与缓存复用的误差可通过校准与命中率监控回退，蒸馏的分布偏移不可逆，投机解码的无偏性最贵但也最安全。一个具体例子：在线自回归视频请求、SLO以单帧时延为主、帧间相关性强且草稿误差可控的场景，选投机解码并把 $k$ 与草稿步数挂在接受率反馈环上；若同一集群里长视频请求占比上升、KV复制触发显存不足，则把长视频路由到缓存复用加量化的路径，短请求留在投机解码路径，按请求形态分流而不是全局二选一。排除条件同样明确：接受率持续偏低、验证batch偏离高效区间、双份KV挤爆显存，三者任一出现即应退出投机解码路径，而不是靠调参硬撑。</p>\n<p>最后落到机制层面：选型的本质是判断瓶颈落在采样链、注意力计算、重复前向还是数值带宽哪一层，投机解码只对“串行采样链”这一层有效，其余层的收益必须由相邻算法承担；把 $k$ 与草稿步数做成接受率的函数，是让这条路径在负载漂移时不至于从收益翻成代价的最小工程约束。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-51\">五十一 · 边界在哪里：同族算法怎么选、何时不该用</h3>\n<p>把本方案放回同族算法谱系里，选择的分水岭不在“能不能加速”，而在“加速的收益是否被自身代价吃掉”。最直接的对照是少步蒸馏：后者直接改写采样链，把目标模型的多步去噪压成一步或两步，单步延迟从根上变短，代价是输出分布被永久改变、质量上限锁死在蒸馏教师的能力里；本方案则保持目标模型分布不变，接受准则 <span class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u,\\quad u\\sim U(0,1)$$</span> 取满足式的最长前缀 $m$，保证无偏。工程判断因此很干脆：若业务能接受分布漂移、且蒸馏质量已达标，选少步蒸馏，显存只放一份权重；若必须严格对齐目标模型分布、又要吃并行验证的吞吐，才轮到本方案，并且必须为双份权重与双份 KV 预留显存。第二组对照是普通文本投机解码——机制同源，但视频侧多出帧 latent 的草稿形态与长视频 KV 复制成本，文本侧那套“k 拉大总不亏”的经验在视频上不成立。</p>\n<p>失效条件可以按期望加速比公式读出方向：<span class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}},\\quad a_j=\\Pr[\\text{accept}_j],\\ \\text{verify batch}=k\\cdot N_{\\text{tok}}$$</span> 分子随 $k$ 增长的速度由连乘 $\\prod_{j\\le i}a_j$ 决定，视频帧间相关性强但草稿误差随 $k$ 快速累积，$a_j$ 逐位下滑使连乘迅速塌陷；分母却随 $k$ 线性抬升草稿开销。于是存在一个临界 $k$：接受率低时验证开销反超收益，时延不降反升。这不是定性担忧，而是可测的拐点——把实测 $a_j$ 序列代入上式，若 $\\mathbb{E}[\\text{speedup}]&lt;1$ 就应立刻收缩 $k$，而不是继续加宽验证 batch。另一条失效路径在显存：草稿与目标双份权重加双份 KV，长视频下 KV 复制成本随序列长度线性膨胀，最先触发的是显存不足而非算力不足，此时任何调度技巧都救不回来。</p>\n<p>第三条边界在硬件效率区间。验证阶段把 $k$ 个候选拼成 batch 走批处理 GEMM，收益的前提是 batch 落在 Tensor Core 高效区间；$k$ 过大使验证 batch 超出该区间，并行验证的吞吐优势被抵消，反而退化成低效的大 batch 空转。这与显存约束是一对反向拉扯：$k$ 太小验证 batch 喂不饱 Tensor Core，$k$ 太大既撞显存又跌出高效区间，可行域是一条窄带。决策表据此给出可操作判据：</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>首选</th><th>本方案的适用条件</th></tr></thead><tbody><tr><td>分布必须严格对齐目标模型</td><td>本方案</td><td>接受率高、$k$ 可动态收缩、显存留双份余量</td></tr><tr><td>可接受分布漂移、追求极限单步延迟</td><td>少步蒸馏</td><td>不适用，双份权重纯属浪费</td></tr><tr><td>帧间相关弱或草稿误差大</td><td>直接目标模型解码</td><td>失效，$\\mathbb{E}[\\text{speedup}]&lt;1$</td></tr><tr><td>超长视频、KV 复制成本主导</td><td>分块/滑窗解码</td><td>失效，双份 KV 先挤爆显存</td></tr></tbody></table>\n<p>把判据落到工程动作上：上线前先用小样本测出各位置的 $a_j$ 曲线与单帧时延基线，据此定 $k$ 的上界与草稿步数档位；运行时按接受率自适应收缩 $k$，把验证 batch 钉在 Tensor Core 高效区间内，同时监控显存水位，一旦双份 KV 逼近上限就降 $k$ 或缩短草稿视野。硬件档位按“目标模型显存 + 草稿模型余量”规划，而不是按目标模型单独规划——这条余量正是本方案相对少步蒸馏多付的系统代价，也是它在长视频场景最先失效的地方。</p>\n\n<h3 id=\"alg-spec-decode-video-ar-sec-52\">五十二 · 选型边界：何时该用投机解码，何时该换别的路</h3>\n<p>与同族算法对照，第一条分界线是<strong>是否允许改变采样链本身</strong>。少步蒸馏、一致性模型这类方案直接压缩采样步数，把目标分布换成近似分布，收益来自“少算”，代价是质量契约被改写；本方案保持目标模型分布不变，接受准则 <span class=\"formula\">$$\\prod_{i=1}^{m}\\frac{p_{\\text{tgt}}(y_i\\mid y_{&lt;i})}{p_{\\text{draft}}(y_i\\mid y_{&lt;i})}\\ge u$$</span> 保证无偏，收益只来自“串行改并行”。因此当业务对帧间一致性、长程漂移极敏感、不接受任何分布偏移时，投机解码是唯一不牺牲质量的选择；反之若草稿模型本身难以训练到低误差，蒸馏路线反而更稳。第二条分界线是<strong>KV 复制的显存账</strong>：普通文本投机解码的 KV 短、可丢弃，而视频长序列下草稿与目标双份权重加双份 KV 是硬约束，规模上限由“目标模型显存 + 草稿余量”直接决定，长视频场景下这笔账往往先于算力成为瓶颈。</p>\n<p>决策时可把期望加速比当作筛选器：<span class=\"formula\">$$\\mathbb{E}[\\text{speedup}]\\approx\\frac{1+\\sum_{i=1}^{k}\\prod_{j\\le i}a_j}{1+k\\,c_{\\text{draft}}/c_{\\text{target}}}$$</span> 其中 $a_j$ 随 $k$ 增大而快速衰减——视频帧间相关性强，但草稿误差同样沿前缀累积，一旦 $a_j$ 掉到使分子增长慢于分母，验证开销就反超收益，时延不降反升。这正是失效条件的量化形态：不是“草稿不够好”，而是“$k$ 与草稿步数没有随接受率收缩”。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>选投机解码</th><th>选少步蒸馏/一致性</th><th>选纯目标模型串行</th></tr></thead><tbody><tr><td>帧间相关强、草稿误差可控</td><td>首选，动态 $k$ 维持验证 batch 在 Tensor Core 高效区间</td><td>可用但改写分布</td><td>浪费冗余</td></tr><tr><td>长视频、KV 复制成本高</td><td>谨慎，双份 KV 易触发显存不足</td><td>显存更省</td><td>显存最省、时延最差</td></tr><tr><td>接受率持续偏低</td><td>失效，需收缩 $k$ 或退回串行</td><td>更稳</td><td>兜底</td></tr></tbody></table>\n<p>工程判断落在自适应回退上：把接受率作为控制量，接受率跌破阈值就收缩 $k$ 与草稿步数，让验证 batch 退回高效区间；若收缩后加速比仍小于 1，说明该负载已越过适用边界，应直接切回纯目标模型串行或改用蒸馏路线，而不是继续加 $k$ 赌接受率。这条回退逻辑本身就是选型结论：投机解码是“帧间冗余可兑现”时的加速器，不是通用默认项。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 稀疏时空注意力与流式长视频</td></tr><tr><td>解决什么</td><td>自回归视频生成逐帧/逐token串行解码，单步延迟受内存带宽与采样链限制；视频帧间强相关，存在可被小模型草拟、大模型并…</td></tr><tr><td>一句话机制</td><td>用轻量草稿模型（少步/低分辨率/低精度）一次提出多帧latent token，目标模型并行验证并接受最长一致前缀，拒绝…</td></tr><tr><td>代价与失效</td><td>视频帧间相关性强但草稿模型误差会随k增大快速累积，接受率低时验证开销反超收益。；草稿与目标模型双份权重与KV占用显存，长视频下KV复制成本…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-spec-decode-video-ar · 共 8 个片段</p>\n";break;}}})();
